      "path": "package.json",
      "content": "{\n  \"name\": \"ai-novel-writer\",\n  \"version\": \"1.4.0\",\n  \"description\": \"AI Novel Writer - a local-first production workspace for long-form fiction\",\n  \"author\": \"AI Novel Writer Maintainers\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.11.0\",\n  \"engines\": {\n    \"node\": \">=22.14.0\"\n  },\n  \"main\": \"dist-electron/main.js\",\n  \"scripts\": {\n    \"postinstall\": \"node node_modules/electron/install.js\",\n    \"dev\": \"vite\",\n    \"clean:build\": \"node scripts/clean-build-output.mjs\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"check:i18n\": \"node scripts/check-i18n-coverage.mjs\",\n    \"test\": \"vitest run\",\n    \"test:browser\": \"vitest run --config vitest.browser.config.ts\",\n    \"verify:drive\": \"node scripts/redesign/drive.mjs\",\n    \"build\": \"tsc && vite build\",\n    \"build:win\": \"pnpm run release:win:verify\",\n    \"build:win:artifacts\": \"node scripts/require-release-gate.mjs && tsc && vite build && electron-builder --win --x64 --publish never\",\n    \"release:win:verify\": \"node scripts/release-win-verify.mjs\",\n    \"build:win-dir\": \"pnpm run clean:build && pnpm run typecheck && vite build && electron-builder --win dir --x64 && pnpm run verify:win-package\",\n    \"build:mac:artifacts\": \"pnpm run build:mac:arm64:artifacts\",\n    \"build:mac:arm64:artifacts\": \"pnpm run clean:build && pnpm run typecheck && clang -fobjc-arc -framework Foundation electron/security/darwin-safe-file-system.m -o electron/security/darwin-safe-file-system && chmod +x electron/security/darwin-safe-file-system && vite build && node scripts/build-release-vector-smoke-runner.mjs && electron-builder --mac --arm64 --publish never\",\n    \"build:mac:x64:artifacts\": \"pnpm run clean:build && pnpm run typecheck && clang -fobjc-arc -framework Foundation electron/security/darwin-safe-file-system.m -o electron/security/darwin-safe-file-system && chmod +x electron/security/darwin-safe-file-system && vite build && node scripts/build-release-vector-smoke-runner.mjs && electron-builder --mac --x64 --publish never\",\n    \"verify:win-package\": \"node scripts/verify-win-package.mjs\",\n    \"verify:win-update-artifacts\": \"node scripts/verify-win-update-artifacts.mjs\",\n    \"verify:github-update-release\": \"node scripts/verify-github-update-release.mjs\",\n    \"smoke:win-app\": \"powershell -NoProfile -ExecutionPolicy Bypass -File scripts/smoke-win-app.ps1\",\n    \"smoke:win-installer\": \"powershell -NoProfile -ExecutionPolicy Bypass -File scripts/smoke-win-installer.ps1\",\n    \"smoke:win-v025-upgrade\": \"powershell -NoProfile -ExecutionPolicy Bypass -File scripts/smoke-win-v025-upgrade.ps1\",\n    \"smoke:mac-dmg\": \"bash scripts/smoke-macos-dmg.sh\",\n    \"lint\": \"eslint . --ext ts,tsx --report-unused-disable-directives --max-warnings 0 && node scripts/check-color-literals.mjs\",\n    \"preview\": \"vite preview\",\n    \"storybook\": \"storybook dev -p 6006\",\n    \"build-storybook\": \"storybook build\"\n  },\n  \"dependencies\": {\n    \"@codemirror/lang-markdown\": \"^6.5.0\",\n    \"@codemirror/language\": \"^6.12.3\",\n    \"@codemirror/language-data\": \"^6.5.2\",\n    \"@codemirror/search\": \"^6.7.1\",\n    \"@codemirror/state\": \"^6.6.0\",\n    \"@codemirror/view\": \"^6.41.0\",\n    \"@lancedb/lancedb\": \"0.22.3\",\n    \"@lezer/highlight\": \"^1.2.3\",\n    \"@radix-ui/react-dialog\": \"^1.1.15\",\n    \"@radix-ui/react-label\": \"^2.1.8\",\n    \"@radix-ui/react-select\": \"^2.2.6\",\n    \"@radix-ui/react-separator\": \"^1.1.8\",\n    \"@radix-ui/react-slot\": \"^1.2.4\",\n    \"@radix-ui/react-tabs\": \"^1.1.13\",\n    \"@radix-ui/react-tooltip\": \"^1.2.8\",\n    \"@uiw/react-codemirror\": \"^4.25.9\",\n    \"apache-arrow\": \"^18.1.0\",\n    \"better-sqlite3\": \"^13.0.3\",\n    \"class-variance-authority\": \"^0.7.1\",\n    \"clsx\": \"^2.1.1\",\n    \"diff-match-patch\": \"^1.0.5\",\n    \"electron-up