    {
      "path": "src/services/workflows/source-selection.ts",
      "content": "import type { CandidateAdmission, CandidateSource, ProjectEpoch, SourceRef } from '../../shared/source-ref'\nimport { mayUseCandidate, sameProjectEpoch } from '../../shared/source-ref'\n\n/** 材料类别按来源性质区分，不建立第二份可写事实库。 */\nexport type MaterialCategory = 'author' | 'finalized-history' | 'future-plan' | 'derived-locator' | 'reference'\nexport type MaterialProvenance = 'author' | 'finalized' | 'generated' | 'derived' | 'legacy' | 'unknown'\n\nexport interface MaterialCandidate {\n  ref: SourceRef\n  category: MaterialCategory\n  provenance: MaterialProvenance\n  /** 必需材料装不下时返回容量冲突，绝不静默裁掉。 */\n  required: boolean\n  text: string\n  /** 角色来源身份；未知来源不得被洗成 author。 */\n  characterId?: string\n  /** 只可用于定位并回读原文，其陈述本身不得进入正文材料。 */\n  locatorOnly?: boolean\n  /** 该来源的定位索引已过期（stale 摘要）。 */\n  staleLocator?: boolean\n  /** 从同一可读来源回读到的不可变原文；stale 定位的唯一合法替代。 */\n  recoveredProse?: readonly string[]\n  /** 未定稿候选材料；只有通过准入的白名单项才可能入选。 */\n  candidate?: { source: CandidateSource; admission: CandidateAdmission }\n}\n\nexport type SourceOmissionReason = 'unknown-provenance' | 'locator-statement-not-evidence' | 'candidate-not-admitted'\n  | 'invalid-source-ref' | 'plot-tree-not-manuscript' | 'duplicate-content' | 'duplicate-source-ref' | 'budget'\n\n/** 这些原因说明来源本身不可用，不是容量问题：再拆小范围也解决不了。 */\nconst UNUSABLE_SOURCE_REASONS: readonly SourceOmissionReason[] = [\n  'unknown-provenance', 'locator-statement-not-evidence', 'candidate-not-admitted',\n  'invalid-source-ref', 'plot-tree-not-manuscript', 'duplicate-source-ref',\n]\n\nexport interface SourceOmission {\n  sourceId: string\n  revision: number\n  contentHash: string\n  reason: SourceOmissionReason\n  category: MaterialCategory\n  required: boolean\n}\n\nexport interface SelectedMaterial {\n  ref: SourceRef\n  category: MaterialCategory\n  text: string\n  required: boolean\n  reason: string\n}\n\nexport interface RequiredCoverage {\n  required: number\n  included: number\n  complete: boolean\n}\n\n/**\n * `remainingRequired` 与 `blockingSourceId` 都是 `sourceId`，同一条源修订被引用\n * 多次时并不唯一。需要精确定位到某一版时，必须与 `omissions`（带 reason /\n * category / required）配合读取；本契约不为此把 payload 换成不可读的身份串。\n */\nexport type SourceSelection =\n  | { decision: 'ready'; included: readonly SelectedMaterial[]; omissions: readonly SourceOmission[]; coverage: RequiredCoverage }\n  | { decision: 'split-required'; remainingRequired: readonly string[]; omissions: readonly SourceOmission[]; coverage: RequiredCoverage }\n  | { decision: 'capacity-conflict'; blockingSourceId: string; blockingReason: SourceOmissionReason\n      omissions: readonly SourceOmission[]; coverage: RequiredCoverage }\n\nexport interface SourceSelectionInput {\n  current: ProjectEpoch\n  candidates: readonly MaterialCandidate[]\n  capacity: { maxInputUnits: number; methodVersion: string }\n  /** Optional material may enter only while total included units stay below this local ceiling. */\n  optionalMaterialCeiling?: number\n  relevanceTerms: readonly string[]\n}\n\nconst PLOT_TREE_PREFIX = 'plot-tree:'\n/** 估计单位固定为 UTF-8 字节；位置单位仍是编辑器的 UTF-16 code unit，本片不产生 span。 */\nconst unitOf = (text: string) => new TextEncoder().encode(text).length\n/** 只用于给可选材料排序，不作为事实判定依据。 */\nconst relevanceOf = (text: string, terms: readonly string[]) => terms.filter(term => term && text.includes(term)).length\n\n/**\n * 码元比较。不用 localeCompare：它依赖 ICU/locale（同一组中文 ID 在 zh-CN 与\n * en-US 下顺序不同），并且会把 collation 等价的字符串判成相等，因而不是全序，\n * 会让排序结果继承输入顺序。\n */\nfunction compareCodeUnit(left: string, right: string): number {\n  return left < right ? -1 : left > right ? 1 : 0\n}\n\n/**\n * 候选的规范序列化。比较器必须对**整条记录**构成全序，否则只在前几个字段上\n * 相等的两条记录会退回输入顺序，进而让选择结果甚至决策依赖调用方传参顺序。\n * 这里把每个决策相关字段都写进固定顺序的数组，比较这个字符串即可。\n */\nfunction canonicalCandidate(candidate: MaterialCandidate): string {\n  const { ref, candidate: draft } = candidate\n  return JSON.stringify([\n    ref.projectId, ref.epoch, ref.sourceId, ref.revision, ref.contentHash,\n    ref.span ? [ref.span.start, ref.span.end, ref.span.unit] : null,\n    candidate.category, candidate.provenance, candidate.required, candidate.text,\n    candidate.characterId ?? null,\n    candidate.locatorOnly ?? false,\n    candidate.staleLocator ?? false,\n    candidate.recoveredProse ? [...candidate.recoveredProse] : null,\n    draft ? [draft.source.artifactId, draft.source.revision, draft.source.state, draft.source.saved,\n      draft.source.batchLineage, draft.admission.selectedCurrentDraftId ?? null,\n      draft.admission.directPredecessorId ?? null] : null,\n  ])\n}\n\nconst compareCandidate = (left: MaterialCandidate, right: MaterialCandidate): number =>\n  compareCodeUnit(canonicalCandidate(left), canonicalCandidate(right))\n\n/**\n * 不可变源身份。同一条源修订被引用两次属于矛盾输入（同一份内容不可能既是\n * author 又是 unknown，也不可能同时必需与可选），必须先拒绝，否则后续的\n * 覆盖与排序判断都得依赖「谁先被处理」。\n */\nfunction sourceIdentity(candidate: MaterialCandidate): string {\n  const { ref } = candidate\n  return JSON.stringify([ref.projectId, ref.epoch, ref.sourceId, ref.revision, ref.contentHash,\n    ref.span ? [ref.span.start, ref.span.end, ref.span.unit] : null])\n}\n\nfunction coverageOf(required: readonly string[], covered: ReadonlySet<string>): RequiredCoverage {\n  const hit = required.filter(contentHash => covered.has(contentHash)).length\n  return { required: required.length, included: hit, complete: hit === required.length }\n}\n\n/**\n * 纯选择接缝：先证明哪些资料可以进入本章，再由调用方接模型。\n * 它不读数据库、不写文件、不发请求；相同输入（含调用方传参顺序）产生相同选择。\n *\n * 必需覆盖按**内容**判定并在选择结束后统一结算，不在循环里提前失败：否则\n * 「必需但自身不产材料的来源」能否被同内容的兄弟来源满足，就取决于谁先被\n * 处理，而不是事实本身。\n */\nexport function selectChapterSources(input: SourceSelectionInput): SourceSelection {\n  const omissions: SourceOmission[] = []\n  const admissible: MaterialCandidate[] = []\n  const ordered = [...input.candidates].sort(compareCandidate)\n  // 必需覆盖按内容统计，重复来源既不会重复进入上下文，也不会让覆盖看起来缺失。\n  const requiredContent = ordered.filter(item => item.required).map(item => item.ref.contentHash)\n  const seenIdentity = new Set<string>()\n  // 阻断原因按**候选对象**记录，而不是按 sourceId 或源身份：同一 sourceId 可以\n  // 合法地出现在不同 revision 上，而同身份的两条候选也可能一条被接受、一条被\n  // 前置规则拒绝，任何字符串键都会让后写覆盖先写、把原因归给另一个候选。\n  const reasonByCandidate = new WeakMap<MaterialCandidate, SourceOmissionReason>()\n  // 省略清单记录所有被排除的材料；阻断原因只记录阻止它进入的那一条。\n  // stale 定位的陈述未被采用是信息性的，来源仍然可用，不能算阻断原因。\n  const markBlock = (candidate: MaterialCandidate, reason: SourceOmissionReason) => {\n    if (!reasonByCandidate.has(candidate)) reasonByCandidate.set(candidate, reason)\n  }\n  const record = (candidate: MaterialCandidate, reason: SourceOmissionReason) => {\n    omissions.push({ sourceId: candidate.ref.sourceId, revision: candidate.ref.revision,\n      contentHash: candidate.ref.contentHash, reason, category: candidate.category, required: candidate.required })\n  }\n  const block = (candidate: MaterialCandidate, reason: SourceOmissionReason) => {\n    record(candidate, reason)\n    markBlock(candidate, reason)\n  }\n\n  for (const candidate of ordered) {\n    const omit = (reason: SourceOmissionReason) => block(candidate, reason)\n    if (!sameProjectEpoch(candidate.ref, input.current) || !candidate.ref.sourceId.trim()\n      || !Number.isSafeInteger(candidate.ref.revision) || candidate.ref.revision < 0) { omit('invalid-source-ref'); continue }\n    if (candidate.ref.sourceId.startsWith(PLOT_TREE_PREFIX)) { omit('plot-tree-not-manuscript'); continue }\n    if (candidate.provenance === 'unknown') { omit('unknown-provenance'); continue }\n    if (candidate.candidate && !mayUseCandidate(candidate.candidate.source, candidate.candidate.admission)) {\n      omit('candidate-not-admitted'); continue\n    }\n    const identity = sourceIdentity(candidate)\n    if (seenIdentity.has(identity)) { omit('duplicate-source-ref'); continue }\n    seenIdentity.add(identity)\n    admissible.push(candidate)\n  }\n\n  const requiredFirst = [...admissible].sort((left, right) => {\n    if (left.required !== right.required) return Number(right.required) - Number(left.required)\n    // 先必需后可选；可选材料之间按本章相关词命中数排序，再按稳定全序收口。\n    if (!left.required) {\n      const delta = relevanceOf(right.text, input.relevanceTerms) - relevanceOf(left.text, input.relevanceTerms)\n      if (delta !== 0) return delta\n    }\n    return compareCandidate(left, right)\n  })\n  const included: SelectedMaterial[] = []\n  const coveredContent = new Set<string>()\n  let remaining = input.capacity.maxInputUnits\n\n  for (const candidate of requiredFirst) {\n    // 同一份不可变内容已由别的来源贡献：只记一次重复省略就够，\n    // 不再叠加第二条定位省略。\n    if (coveredContent.has(candidate.ref.contentHash)) {\n      block(candidate, 'duplicate-content')\n      continue\n    }\n    const blocks = candidate.staleLocator\n      ? (candidate.recoveredProse ?? []).map(text => ({ text, reason: 'recovered immutable prose for a stale locator' }))\n      : candidate.locatorOnly ? [] : [{ text: candidate.text, reason: `${candidate.category} material` }]\n    if (candidate.staleLocator) record(candidate, 'locator-statement-not-evidence')\n    if (blocks.length === 0) {\n      // 只可定位、且没有可回读原文的来源本身不产生材料。它能否被满足由结算阶段\n      // 按最终内容判断：同内容的兄弟来源进得来就算满足，否则整体失败。\n      // stale 定位已经记过同一条省略，这里不再重复。\n      if (candidate.staleLocator) markBlock(candidate, 'locator-statement-not-evidence')\n      else block(candidate, 'locator-statement-not-evidence')\n      continue\n    }\n    const cost = blocks.reduce((sum, piece) => sum + unitOf(piece.text), 0)\n    if (cost > remaining || !candidate.required && input.optionalMaterialCeiling !== undefined\n      && input.capacity.maxInputUnits - remaining + cost > input.optionalMaterialCeiling) {\n      block(candidate, 'budget')\n      continue\n    }\n    remaining -= cost\n    for (const piece of blocks) {\n      included.push({ ref: candidate.ref, category: candidate.category, text: piece.text,\n        required: candidate.required, reason: piece.reason })\n    }\n    coveredContent.add(candidate.ref.contentHash)\n  }\n\n  const coverage = coverageOf(requiredContent, coveredContent)\n  if (coverage.complete) return { decision: 'ready', included, omissions, coverage }\n\n  // 结算：按稳定顺序挑出第一个未被覆盖的必需来源作为阻断点。\n  const blocking = ordered.find(item => item.required && !coveredContent.has(item.ref.contentHash))!\n  // blocking 取自 ordered，是同一个对象引用，因此这里取到的就是它自己的原因。\n  const reason = reasonByCandidate.get(blocking) ?? 'budget'\n  if (UNUSABLE_SOURCE_REASONS.includes(reason)) {\n    // 来源本身不可用：拆小范围也解决不了。\n    return { decision: 'capacity-conflict', blockingSourceId: blocking.ref.sourceId,\n      blockingReason: reason, omissions, coverage }\n  }\n  return coverage.included === 0\n    ? { decision: 'capacity-conflict', blockingSourceId: blocking.ref.sourceId,\n        blockingReason: reason, omissions, coverage }\n    : { decision: 'split-required', remainingRequired: ordered\n        .filter(item => item.required && !coveredContent.has(item.ref.contentHash))\n        .map(item => item.ref.sourceId), omissions, coverage }\n}\n"
    },
    {
      "path": "src/services/workflows/chapter-materials.ts",
      "content": "import type { WritingLanguage } from '../../shared/writing-language'\nimport { hashAuthorText } from '../../shared/source-ref'\nimport {\n  MATERIAL_DECISION_MAX_INPUT_UNITS,\n  MATERIAL_DECISION_RECEIPT_VERSION,\n  MATERIAL_DECISION_UNIT_METHOD_VERSION,\n  type MaterialDecisionIncludedSource,\n  type MaterialDecisionOmittedSource,\n  type MaterialDecisionDraft,\n} from '../../shared/generation-owner-contract'\nimport type { ReviewMaterialIdentity } from '../../shared/review-revision-generation'\nimport { promptLanguageText } from '../prompt-language'\nimport {\n  selectChapterSources,\n  type MaterialCandidate,\n  type MaterialCategory,\n  type SourceOmission,\n  type SourceOmissionReason,\n  type SourceSelection,\n} from './source-selection'\n\nexport interface SelectedCandidateDraft {\n  chapterNumber: number\n  draftId: number\n  version: number\n  content: string\n  /** Required predecessor for this run. Omitted on the legacy single-candidate path. */\n  required?: boolean\n}\n\nexport interface FinalizedMaterialSource {\n  chapterNumber: number\n  draftId: number\n  title: string\n  content: string\n  evidence: readonly string[]\n  includeEnding?: boolean\n  sourceStatus?: 'current' | 'stale' | 'legacy' | 'invalid'\n  sourceIdentity?:\n    | { kind: 'finalized'; finalizationId: string; contentHash: string }\n    | { kind: 'legacy-finalized' }\n}\n\nexport interface ChapterMaterialOmission {\n  source: 'finalized' | 'candidate' | 'reference'\n  chapterNumber?: number\n  /**\n   * `evidence-not-locatable` / `source-invalid` / `no-relevant-passage` 由材料摘取给出，\n   * `budget` / `duplicate-content` 由选择契约的容量与内容唯一性结算给出。\n   */\n  reason: 'evidence-not-locatable' | 'source-invalid' | 'no-relevant-passage' | 'budget' | 'duplicate-content'\n}\n\nexport interface ChapterMaterialReference {\n  readonly text: string\n  readonly rendered: string\n  readonly deduplicateAgainstFinalized?: boolean\n}\n\nexport interface ChapterMaterialBundle {\n  text: string\n  previousEnding: string\n  includedFinalizedFacts: number\n  consumedFinalizedSources: FinalizedMaterialSource[]\n  omissions: ChapterMaterialOmission[]\n}\n\n/** 稳定准入需要的项目身份。epoch 与主进程 generation binding 一致，取会话 lease。 */\nexport interface ChapterMaterialIdentity {\n  projectId: string\n  epoch: string\n}\n\n/**\n * 合同省略原因 -> 装配层省略原因。\n *\n * 装配层的联合体比合同窄，这里做一次有损投影：写稿路径上可达的只有 `budget` 与\n * `duplicate-content`（其余原因需要 provenance=unknown、`plot-tree:` 前缀、locatorOnly\n * 或候选准入字段，而本函数从不构造这类候选），它们一律归为 `source-invalid`——都表示\n * 「这条来源不可用」。\n */\nconst SELECTION_OMISSION_REASON: Record<SourceOmissionReason, ChapterMaterialOmission['reason']> = {\n  budget: 'budget',\n  'duplicate-content': 'duplicate-content',\n  'duplicate-source-ref': 'duplicate-content',\n  'invalid-source-ref': 'source-invalid',\n  'unknown-provenance': 'source-invalid',\n  'plot-tree-not-manuscript': 'source-invalid',\n  'candidate-not-admitted': 'source-invalid',\n  'locator-statement-not-evidence': 'source-invalid',\n}\n\n/**\n * 必需材料（作者资料 + 角色档案 + 后续计划）装不下容量时的唯一结果。\n *\n * 它携带合同的原始裁决（谁被阻断、原因、覆盖缺口），调用方据此给出可执行提示；\n * 绝不静默截断、也不静默丢掉必需材料。\n */\nexport class ChapterMaterialCapacityError extends Error {\n  readonly code = 'CHAPTER_MATERIAL_CAPACITY_CONFLICT' as const\n\n  constructor(\n    readonly decision: Extract<SourceSelection, { decision: 'split-required' | 'capacity-conflict' }>,\n    locale: WritingLanguage,\n  ) {\n    const blocked = decision.decision === 'capacity-conflict'\n      ? `${decision.blockingSourceId} (${decision.blockingReason})`\n      : decision.remainingRequired.join(', ')\n    super(locale === 'en-US'\n      ? `Required chapter material does not fit the context capacity (${decision.decision}): ${blocked}. Trim the author material or future plans and try again.`\n      : `本章必需材料装不下上下文容量（${decision.decision}）：${blocked}。请精简作者资料、角色档案或后续计划后重试。`)\n    this.name = 'ChapterMaterialCapacityError'\n  }\n}\n\n/**\n * S10B-1b：选择契约是提示词材料的唯一权威。渲染、省略清单与依赖清单全部由\n * `selectChapterSources` 的一次裁决推出；传统遍历已经删除，不再存在第二条准入路径。\n */\nexport interface ChapterMaterialAssembly extends ChapterMaterialBundle {\n  selection: Extract<SourceSelection, { decision: 'ready' }>\n  /** 脱敏准入收据：随主进程冻结上下文一起持久化，并被恢复指纹绑定。 */\n  decision: MaterialDecisionDraft\n}\n\n/**\n * 材料准入裁决 -> 脱敏收据（S10B 步骤 3）。\n *\n * 收据只承载**可核对的编号**：来源 id、修订、已渲染材料的内容哈希、类别、是否必需、\n * UTF-8 字节数、省略原因码、必需覆盖计数与容量裁决。正文、作者文字、路径与凭据一律\n * 不进收据——「收据记明确认了什么」与「公开日志不放正文」是同一件事的两面。\n *\n * 只有 `ready` 裁决才配得上收据：容量冲突与拆分在调用方就已显式失败，根本不会开出\n * 运行，也就不存在可绑定的指纹。这里因此对非 `ready` 输入直接抛错，绝不用半份裁决\n * 冒充收据。\n *\n * 同一来源可能拆成多个片段进入材料（stale 定位回读、多段证据窗口），这里按\n * `(sourceId, revision, contentHash)` 合并为一个来源条目并累加字节数，使收据记录的是\n * **来源级**准入，而不是渲染分块。排序用码元比较的稳定全序，不依赖 locale。\n */\nexport function buildMaterialDecisionReceipt(\n  selection: SourceSelection,\n  capacity: { maxInputUnits: number; methodVersion: typeof MATERIAL_DECISION_UNIT_METHOD_VERSION },\n  additionalOmissions: readonly MaterialDecisionOmittedSource[] = [],\n): MaterialDecisionDraft {\n  if (selection.decision !== 'ready') throw new Error('MATERIAL_DECISION_NOT_READY')\n  if (!Number.isSafeInteger(capacity.maxInputUnits) || capacity.maxInputUnits < 1\n    || capacity.maxInputUnits > MATERIAL_DECISION_MAX_INPUT_UNITS)\n    throw new Error('MATERIAL_DECISION_CAPACITY_INVALID')\n  const included = new Map<string, MaterialDecisionIncludedSource>()\n  for (const material of selection.included) {\n    const key = materialIdentityKey(material.ref)\n    const units = new TextEncoder().encode(material.text).length\n    if (units < 1) throw new Error('MATERIAL_DECISION_INCLUDED_EMPTY')\n    const existing = included.get(key)\n    if (existing) {\n      if (existing.category !== material.category || existing.required !== material.required)\n        throw new Error('MATERIAL_DECISION_INCLUDED_IDENTITY_CONFLICT')\n      existing.units += units\n      continue\n    }\n    included.set(key, {\n      sourceId: material.ref.sourceId,\n      revision: material.ref.revision,\n      contentHash: material.ref.contentHash,\n      category: material.category,\n      required: material.required,\n      units,\n    })\n  }\n  const ordered = [...included.values()].sort((left, right) =>\n    compareCodeUnit(left.sourceId, right.sourceId)\n    || left.revision - right.revision\n    || compareCodeUnit(left.contentHash, right.contentHash))\n  const omitted: MaterialDecisionOmittedSource[] = [\n    ...selection.omissions.map(omission => ({\n      sourceId: omission.sourceId,\n      revision: omission.revision,\n      contentHash: omission.contentHash,\n      reason: omission.reason,\n      category: omission.category,\n      required: omission.required,\n    })),\n    ...additionalOmissions,\n  ]\n    .sort((left, right) =>\n      compareCodeUnit(left.sourceId, right.sourceId)\n      || left.revision - right.revision\n      || compareCodeUnit(left.contentHash, right.contentHash)\n      || compareCodeUnit(left.reason, right.reason)\n      || compareCodeUnit(left.category, right.category)\n      || Number(left.required) - Number(right.required))\n  const omittedEvents = omitted.map(item => `${materialIdentityKey(item)}\\u0000${item.reason}`)\n  if (new Set(omittedEvents).size !== omittedEvents.length)\n    throw new Error('MATERIAL_DECISION_DUPLICATE_OMISSION')\n  const includedIdentities = new Set(ordered.map(materialIdentityKey))\n  if (omitted.some(item => includedIdentities.has(materialIdentityKey(item))\n    && item.reason !== 'locator-statement-not-evidence' && item.reason !== 'evidence-not-locatable'))\n    throw new Error('MATERIAL_DECISION_IDENTITY_CONFLICT')\n  const admittedUnits = ordered.reduce((sum, item) => sum + item.units, 0)\n  if (admittedUnits > capacity.maxInputUnits)\n    throw new Error('MATERIAL_DECISION_CAPACITY_INVALID')\n  return {\n    version: MATERIAL_DECISION_RECEIPT_VERSION,\n    verdict: 'admitted',\n    capacity: {\n      maxInputUnits: capacity.maxInputUnits,\n      methodVersion: capacity.methodVersion,\n      admittedUnits,\n    },\n    coverage: { required: selection.coverage.required, included: selection.coverage.included, complete: selection.coverage.complete },\n    included: ordered,\n    omitted,\n  }\n}\n\n/** 码元比较：与选择契约同一套全序，避免排序依赖 ICU/locale。 */\nfunction compareCodeUnit(left: string, right: string): number {\n  return left < right ? -1 : left > right ? 1 : 0\n}\n\nconst MATERIAL_BUDGET_CHARS = 6_000\nconst PREVIOUS_ENDING_MAX_CHARS = 1_000\n/**\n * 单位统一（S10B-1b）：旧遍历按 UTF-16 码元计量，选择契约按 UTF-8 字节计量\n * （估算器版本冻结为 `utf8-bytes-v1`）。这里按**写作语言的主要字符集**把码元预算换算成\n * 字节，使切换前后同一条路径的有效材料上限保持同一量级：CJK 一个码元约 3 字节，\n * 拉丁字母一个码元 1 字节。用固定倍数会把另一条路径的上限放大或缩小到 3 倍。\n */\nconst BYTES_PER_BUDGET_CHAR: Readonly<Record<WritingLanguage, number>> = { 'zh-CN': 3, 'en-US': 1 }\n/** `SourceRef.sourceId` 里的家族前缀；渲染与省略清单都按它归类。 */\nconst REQUIRED_SOURCE_ID = 'author:required'\n\n// ---- 审稿/修稿入口的准入层（S10B-2）----\n// 写稿路径在 `assembleChapterMaterials` 里把「渲染」和「准入」合在一个函数里，因为材料文本\n// 本身由它生成。审/修入口的材料文本由各自命令按**原有措辞**渲染好后传入，所以这里只做准入。\n// 成员判定的语义与写稿路径完全一致：同一份不可变内容只进一次、未知来源不得进入、\n// 来源与覆盖仍由同一个 selectChapterSources 校验；审修的完整请求容量由 main 准入。\n\n/** 审稿/修稿入口的一条材料：主进程捕获的身份 + 该入口自己的渲染文本。 */\nexport interface ReviewRevisionMaterial {\n  /** 主进程捕获的不可变来源身份；渲染层不得自行编造来源。 */\n  identity: ReviewMaterialIdentity\n  category: MaterialCategory\n  /** 必需材料装不下时整轮显式失败，绝不静默丢弃。 */\n  required: boolean\n  /** 该材料在本入口提示词里的文本（块头按各入口原有措辞由调用方给出）。 */\n  text: string\n}\n\nexport interface ReviewRevisionMaterialAdmission {\n  selection: Extract<SourceSelection, { decision: 'ready' }>\n  decision: MaterialDecisionDraft\n  /**\n   * 准入的材料，**保持调用方传入顺序**。\n   *\n   * 顺序是刻意的：合同的 `included` 按「必需优先 + 相关度 + 规范全序」排列，那是写稿路径\n   * 的渲染顺序。审/修入口不得因此重排历史（重排会改提示词），所以这里只按身份判定成员，\n   * 再由调用方按原有顺序渲染——准入没有真正改变集合时，提示词逐字节与接入前相同。\n   */\n  admitted: readonly ReviewRevisionMaterial[]\n}\n\n/** 材料身份键：只取合同判定「同一份不可变内容」的字段，不含渲染文本。 */\nfunction materialIdentityKey(identity: { sourceId: string; revision: number; contentHash: string }): string {\n  return JSON.stringify([identity.sourceId, identity.revision, identity.contentHash])\n}\n\n/**\n * 审稿/修稿入口共享来源与覆盖校验。合法必需材料保留到现有收据安全上限，\n * 完整模型请求由 main 准入；局部选材额度只限制可选历史，不裁掉必需材料。\n * 来源或安全上限冲突仍抛 ChapterMaterialCapacityError。\n *\n * 会话租约在这里按**当前会话**补上：冻结材料身份是会话无关的（不含 `epoch`），而\n * `SourceRef` 必须带上活跃租约才能通过 `sameProjectEpoch`。重开同一项目后租约变化，\n * 冻结材料仍然合法——这正是把租约放在使用点、而不是冻进来源清单的原因。\n *\n * 本函数不读数据库、不写文件、不发请求。\n */\nexport function selectReviewRevisionMaterials(input: {\n  current: ChapterMaterialIdentity\n  writingLanguage: WritingLanguage\n  materials: readonly ReviewRevisionMaterial[]\n  relevanceTerms: readonly string[]\n  budgetChars?: number\n}): ReviewRevisionMaterialAdmission {\n  const candidates: MaterialCandidate[] = input.materials.map(material => ({\n    ref: {\n      projectId: material.identity.projectId, epoch: input.current.epoch,\n      sourceId: material.identity.sourceId, revision: material.identity.revision,\n      contentHash: material.identity.contentHash,\n    },\n    category: material.category,\n    provenance: material.identity.provenance,\n    required: material.required,\n    text: material.text,\n  }))\n  // The receipt limit is already in UTF-8 units; it is not a model window or a character allowance.\n  const capacity = {\n    maxInputUnits: MATERIAL_DECISION_MAX_INPUT_UNITS,\n    methodVersion: MATERIAL_DECISION_UNIT_METHOD_VERSION,\n  }\n  const selection = selectChapterSources({\n    current: input.current,\n    capacity,\n    optionalMaterialCeiling: (input.budgetChars ?? MATERIAL_BUDGET_CHARS) * BYTES_PER_BUDGET_CHAR[input.writingLanguage],\n    relevanceTerms: input.relevanceTerms,\n    candidates,\n  })\n  if (selection.decision !== 'ready') throw new ChapterMaterialCapacityError(selection, input.writingLanguage)\n  const admittedKeys = new Set(selection.included.map(item => materialIdentityKey(item.ref)))\n  return {\n    selection,\n    decision: buildMaterialDecisionReceipt(selection, capacity),\n    admitted: input.materials.filter(material => admittedKeys.has(materialIdentityKey(material.identity))),\n  }\n}\n\n/**\n * 没有主进程身份的历史材料一律按 `unknown` 来源对待：合同会以 `invalid-source-ref` /\n * `unknown-provenance` 排除它，必需项因此显式失败。绝不用渲染层自己编的来源顶替。\n * 这里只给出会话无关的最小身份；活跃租约由 `selectReviewRevisionMaterials` 按当前会话补上。\n */\nexport function unknownReviewMaterialIdentity(current: ChapterMaterialIdentity): ReviewMaterialIdentity {\n  return { projectId: current.projectId, sourceId: '', revision: 0, contentHash: '', provenance: 'unknown' }\n}\n\nfunction paragraphs(content: string): string[] {\n  return content.split(/\\r?\\n\\s*\\r?\\n/u).map(part => part.trim()).filter(Boolean)\n}\n\nfunction mergeWindows(windows: Array<[number, number]>): Array<[number, number]> {\n  const merged: Array<[number, number]> = []\n  for (const window of windows.sort((left, right) => left[0] - right[0])) {\n    const previous = merged.at(-1)\n    if (!previous || window[0] > previous[1] + 1) {\n      merged.push([...window])\n    } else {\n      previous[1] = Math.max(previous[1], window[1])\n    }\n  }\n  return merged\n}\n\n/** Keep the hit paragraph plus one complete neighbour on each side. */\nexport function adjacentEvidencePassages(\n  content: string,\n  evidence: readonly string[],\n  includeEnding = false,\n): { passages: string[]; locatedEvidence: number } {\n  const sourceParagraphs = paragraphs(content)\n  const windows: Array<[number, number]> = []\n  let locatedEvidence = 0\n  for (const quote of evidence.map(value => value.trim()).filter(Boolean)) {\n    const index = sourceParagraphs.findIndex(paragraph => paragraph.includes(quote))\n    if (index < 0) continue\n    locatedEvidence += 1\n    windows.push([Math.max(0, index - 1), Math.min(sourceParagraphs.length - 1, index + 1)])\n  }\n  if (includeEnding && sourceParagraphs.length > 0) {\n    windows.push([Math.max(0, sourceParagraphs.length - 2), sourceParagraphs.length - 1])\n  }\n  return {\n    passages: mergeWindows(windows).map(([start, end]) => sourceParagraphs.slice(start, end + 1).join('\\n\\n')),\n    locatedEvidence,\n  }\n}\n\nexport function previousChapterEnding(content: string): string {\n  const trimmed = content.trim()\n  if (trimmed.length <= PREVIOUS_ENDING_MAX_CHARS) return trimmed\n\n  const tail = trimmed.slice(-PREVIOUS_ENDING_MAX_CHARS)\n  const firstBoundary = /(?:\\r?\\n\\s*\\r?\\n|[。！？!?][”’\"'）)\\]】」』]*|\\.[”’\"')\\]]*(?=\\s|$))/u.exec(tail)\n  return firstBoundary\n    ? tail.slice(firstBoundary.index + firstBoundary[0].length).trim() || tail.trim()\n    : tail.trim()\n}\n\nfunction relevantPassages(content: string, terms: readonly string[]): string[] {\n  const sourceParagraphs = paragraphs(content)\n  const normalizedTerms = terms.map(term => term.trim().toLocaleLowerCase()).filter(term => term.length >= 2)\n  const windows: Array<[number, number]> = []\n  for (let index = 0; index < sourceParagraphs.length; index += 1) {\n    const value = sourceParagraphs[index].toLocaleLowerCase()\n    if (normalizedTerms.some(term => value.includes(term))) {\n      windows.push([Math.max(0, index - 1), Math.min(sourceParagraphs.length - 1, index + 1)])\n    }\n  }\n  const merged = mergeWindows(windows)\n  return merged.slice(-2)\n    .map(([start, end]) => sourceParagraphs.slice(start, end + 1).join('\\n\\n'))\n}\n\nfunction removeContainedPassages(passages: readonly string[]): string[] {\n  return passages.filter((passage, index) => !passages.some((other, otherIndex) => (\n    otherIndex !== index\n    && other.includes(passage)\n    && (other.length > passage.length || otherIndex < index)\n  )))\n}\n\n/**\n * 定稿来源在本章的材料文本。摘取逻辑只有这一处：两套各自实现一份就会变成两个事实来源。\n */\nfunction finalizedPassages(source: FinalizedMaterialSource, relevanceTerms: readonly string[]): {\n  passages: string[]\n  locatedEvidence: number\n} {\n  const located = adjacentEvidencePassages(source.content, source.evidence, source.includeEnding)\n  const expectedEvidence = source.evidence.filter(value => value.trim()).length\n  // A stale locator is only an index failure. Recover nearby immutable prose from\n  // the same readable source with the existing deterministic term matcher, while\n  // never injecting the old statement itself.\n  const recovered = located.locatedEvidence < expectedEvidence\n    ? relevantPassages(source.content, relevanceTerms) : []\n  // 上一章结尾是本章续写的时点锚点，必进定稿块，不依赖模型上次定稿时给出的证据位置；\n  // 与 candidatePassages 的必需前驱同一写法。结尾不是证据，不计入 locatedEvidence。\n  const ending = source.includeEnding ? [previousChapterEnding(source.content)] : []\n  return {\n    passages: removeContainedPassages([...located.passages, ...recovered, ...ending].filter(Boolean)),\n    locatedEvidence: located.locatedEvidence,\n  }\n}\n\n/** 未定稿候选在本章的材料文本；同上，只有一处计算。 */\nfunction candidatePassages(candidate: SelectedCandidateDraft, isRequired: boolean,\n  relevanceTerms: readonly string[]): string[] {\n  if (isRequired) return candidate.content.trim() ? [candidate.content] : []\n  return relevantPassages(candidate.content, relevanceTerms)\n}\n\n/** 每条候选在渲染与账目上额外需要的信息，只能由本函数的构造过程给出。 */\ninterface MaterialFamily {\n  family: ChapterMaterialOmission['source'] | 'required'\n  chapterNumber?: number\n  locatedEvidence: number\n  passages: readonly string[]\n  source?: FinalizedMaterialSource\n}\n\nexport async function assembleChapterMaterials(input: {\n  identity: ChapterMaterialIdentity\n  writingLanguage: WritingLanguage\n  authorProjectFacts: readonly string[]\n  characterProfiles: string\n  futurePlans: string\n  references: readonly ChapterMaterialReference[]\n  finalized: readonly FinalizedMaterialSource[]\n  candidates: readonly SelectedCandidateDraft[]\n  relevanceTerms: readonly string[]\n  budgetChars?: number\n}): Promise<ChapterMaterialAssembly> {\n  const writingLanguage = input.writingLanguage\n  const omissions: ChapterMaterialOmission[] = []\n  const decisionOmissions: MaterialDecisionOmittedSource[] = []\n  const candidates: MaterialCandidate[] = []\n  const familyBySourceId = new Map<string, MaterialFamily>()\n  const referenceCandidates: Array<{ candidate: MaterialCandidate; reference: ChapterMaterialReference }> = []\n  const orderedCandidates = [...input.candidates].sort((left, right) => left.chapterNumber - right.chapterNumber)\n  const explicitRequiredCandidates = orderedCandidates.filter(candidate => candidate.required === true)\n  if (orderedCandidates.length > 1 && explicitRequiredCandidates.length !== 1) {\n    throw new Error('CHAPTER_MATERIAL_REQUIRED_PREDECESSOR_AMBIGUOUS')\n  }\n  const requiredPredecessor = orderedCandidates.length === 1\n    ? orderedCandidates[0]\n    : explicitRequiredCandidates[0]\n  const predecessorSource = requiredPredecessor\n    ? undefined\n    : input.finalized.find(source => source.includeEnding && source.sourceStatus !== 'invalid' && source.content.trim())\n\n  const push = async (family: MaterialFamily, material: {\n    sourceId: string\n    revision: number\n    text: string\n    category: MaterialCandidate['category']\n    provenance: MaterialCandidate['provenance']\n    required: boolean\n    staleLocator?: false\n  }): Promise<MaterialCandidate | undefined> => {\n    // 没有材料文本的来源贡献不了任何东西；如果给它建候选，只会在省略清单里\n    // 冒出一个成本为 0 的假纳入。\n    if (!material.text.trim()) return undefined\n    const candidate: MaterialCandidate = {\n      ref: {\n        projectId: input.identity.projectId, epoch: input.identity.epoch,\n        sourceId: material.sourceId, revision: material.revision,\n        contentHash: await hashAuthorText(material.text),\n      },\n      category: material.category, provenance: material.provenance, required: material.required,\n      text: material.text,\n      ...(material.staleLocator === undefined ? {} : { staleLocator: material.staleLocator }),\n    }\n    candidates.push(candidate)\n    familyBySourceId.set(material.sourceId, family)\n    return candidate\n  }\n  const recordDecisionOmission = async (input: {\n    sourceId: string\n    revision: number\n    contentHash?: string\n    text?: string\n    reason: MaterialDecisionOmittedSource['reason']\n    category: MaterialDecisionOmittedSource['category']\n    required?: boolean\n  }): Promise<void> => {\n    decisionOmissions.push({\n      sourceId: input.sourceId,\n      revision: input.revision,\n      contentHash: input.contentHash ?? await hashAuthorText(input.text ?? ''),\n      reason: input.reason,\n      category: input.category,\n      required: input.required ?? false,\n    })\n  }\n\n  // ---- 必需材料（决定 1B）：作者资料 + 角色档案 + 后续计划是单一候选，----\n  // ---- 装不下就整轮失败，绝不静默截断，也绝不让它挤掉别的块。            ----\n  const authorFacts = [...new Set(input.authorProjectFacts.map(value => value.trim()).filter(Boolean))]\n  const required = promptLanguageText(\n    writingLanguage,\n    `【作者资料（保留原文；人物状态具有时点，不是永久约束）】\\n${[...authorFacts, input.characterProfiles].filter(Boolean).join('\\n\\n') || '（无补充作者资料）'}\\n\\n【后续计划边界（只约束当前章，不是当前章任务）】\\n以下保留作者后续计划原文，只用于防止本章提前执行。明确安排在后续章节的知情变化、物品转交、行动和完成状态不得前移；允许不改变这些时点的铺垫。\\n${input.futurePlans}`,\n    `[Author material (verbatim; character state is time-bound, not permanent)]\\n${[...authorFacts, input.characterProfiles].filter(Boolean).join('\\n\\n') || '(no additional author material)'}\\n\\n[Future-plan boundary (constrains the current chapter; not a current-chapter task)]\\nThe author's future plans are preserved verbatim below and only prevent premature execution in this chapter. Knowledge changes, item transfers, actions, and completed states explicitly assigned to later chapters must not be moved earlier; foreshadowing that does not change those timings is allowed.\\n${input.futurePlans}`,\n  )\n  const sourced = promptLanguageText(\n    writingLanguage,\n    '【有来源的历史与候选】\\n以下定稿原文只证明原文直接写明的内容；索引、摘要和 currentState 都不是作者事实。候选正文尚未确认，不得冒充定稿。',\n    '[Sourced history and candidates]\\nFinalized excerpts establish only their exact text; indexes, summaries, and currentState are not author facts. Candidate prose is unconfirmed and is not finalized history.',\n  )\n  const requiredCandidate = await push({ family: 'required', locatedEvidence: 0, passages: [] }, {\n    sourceId: REQUIRED_SOURCE_ID, revision: 1, text: required,\n    category: 'author', provenance: 'author', required: true,\n  })\n\n  const finalizedMaterial = (source: FinalizedMaterialSource, passages: readonly string[], isRequired: boolean) => ({\n    sourceId: `finalized:${source.draftId}`,\n    revision: source.draftId,\n    text: promptLanguageText(\n      writingLanguage,\n      `【定稿原文 · 第${source.chapterNumber}章 · draft ${source.draftId}】\\n${passages.join('\\n\\n')}`,\n      `[Finalized manuscript · Chapter ${source.chapterNumber} · draft ${source.draftId}]\\n${passages.join('\\n\\n')}`,\n    ),\n    category: 'finalized-history' as const,\n    provenance: source.sourceStatus === 'legacy' ? 'legacy' as const : 'finalized' as const,\n    required: isRequired,\n    // stale 定位只说明索引失效：回读到的原文照常计入材料，过时陈述本身从不进入提示词。\n    // 定位状态只留在 consumedFinalizedSources / 决策里，不再印进模型可见的标题。\n    ...(source.sourceStatus === 'stale' ? { staleLocator: false as const } : {}),\n  })\n\n  // ---- 定稿来源 ----\n  // 摘取顺序仍是新章在前，这样摘取层的省略清单保持稳定；**渲染顺序由合同决定**。\n  for (const source of [...input.finalized].sort((left, right) => right.chapterNumber - left.chapterNumber)) {\n    if (source.sourceStatus === 'invalid') {\n      omissions.push({\n        source: 'finalized',\n        chapterNumber: source.chapterNumber,\n        reason: 'source-invalid',\n      })\n      await recordDecisionOmission({\n        sourceId: `finalized:${source.draftId}`,\n        revision: source.draftId,\n        text: source.content,\n        reason: 'source-invalid',\n        category: 'finalized-history',\n      })\n      continue\n    }\n    const extracted = finalizedPassages(source, input.relevanceTerms)\n    const isRequired = source === predecessorSource\n    const passages = isRequired ? [source.content] : extracted.passages\n    const expectedEvidence = source.evidence.filter(value => value.trim()).length\n    const hasUnlocatedEvidence = extracted.locatedEvidence < expectedEvidence\n    if (hasUnlocatedEvidence) {\n      omissions.push({\n        source: 'finalized',\n        chapterNumber: source.chapterNumber,\n        reason: 'evidence-not-locatable',\n      })\n    }\n    if (passages.length === 0) {\n      await recordDecisionOmission({\n        sourceId: `finalized:${source.draftId}`,\n        revision: source.draftId,\n        text: source.content,\n        reason: hasUnlocatedEvidence ? 'evidence-not-locatable' : 'no-relevant-passage',\n        category: 'finalized-history',\n      })\n      continue\n    }\n    const selected = await push({\n      family: 'finalized',\n      chapterNumber: source.chapterNumber,\n      locatedEvidence: extracted.locatedEvidence,\n      passages,\n      source,\n    }, finalizedMaterial(source, passages, isRequired))\n    if (hasUnlocatedEvidence && selected) {\n      await recordDecisionOmission({\n        sourceId: selected.ref.sourceId,\n        revision: selected.ref.revision,\n        contentHash: selected.ref.contentHash,\n        reason: 'evidence-not-locatable',\n        category: selected.category,\n      })\n    }\n  }\n\n  // ---- 未定稿候选 ----\n  let requiredPredecessorMaterial: MaterialCandidate | undefined\n  for (const candidate of orderedCandidates) {\n    const isRequired = candidate === requiredPredecessor\n    const passages = candidatePassages(candidate, isRequired, input.relevanceTerms)\n    if (passages.length === 0) {\n      omissions.push({ source: 'candidate', chapterNumber: candidate.chapterNumber, reason: 'no-relevant-passage' })\n      await recordDecisionOmission({\n        sourceId: `candidate:${candidate.draftId}`,\n        revision: candidate.version,\n        text: candidate.content,\n        reason: 'no-relevant-passage',\n        category: 'finalized-history',\n        required: isRequired,\n      })\n      continue\n    }\n    const material = await push({ family: 'candidate', chapterNumber: candidate.chapterNumber, locatedEvidence: 0, passages: [] }, {\n      sourceId: `candidate:${candidate.draftId}`,\n      revision: candidate.version,\n      text: promptLanguageText(\n        writingLanguage,\n        `【未定稿候选 · 第${candidate.chapterNumber}章 · draft ${candidate.draftId} · v${candidate.version}】\\n${passages.join('\\n\\n')}`,\n        `[Unfinalized candidate · Chapter ${candidate.chapterNumber} · draft ${candidate.draftId} · v${candidate.version}]\\n${passages.join('\\n\\n')}`,\n      ),\n      category: 'finalized-history',\n      provenance: 'author',\n      required: isRequired,\n    })\n    if (isRequired) requiredPredecessorMaterial = material\n  }\n  if (requiredPredecessor && !requiredPredecessorMaterial) {\n    throw new ChapterMaterialCapacityError({\n      decision: 'capacity-conflict',\n      blockingSourceId: `candidate:${requiredPredecessor.draftId}`,\n      blockingReason: 'invalid-source-ref',\n      omissions: [],\n      coverage: { required: 2, included: 0, complete: false },\n    }, writingLanguage)\n  }\n\n  // ---- 参考材料 ----\n  for (const [referenceIndex, reference] of input.references.entries()) {\n    const candidate = await push({ family: 'reference', locatedEvidence: 0, passages: [] }, {\n      sourceId: `reference:${referenceIndex}`,\n      revision: 1,\n      text: reference.rendered,\n      category: 'reference',\n      provenance: 'author',\n      required: false,\n    })\n    if (candidate) referenceCandidates.push({ candidate, reference })\n    else {\n      await recordDecisionOmission({\n        sourceId: `reference:${referenceIndex}`,\n        revision: 1,\n        text: reference.rendered,\n        reason: 'no-relevant-passage',\n        category: 'reference',\n      })\n    }\n  }\n\n  const capacity = {\n    maxInputUnits: MATERIAL_DECISION_MAX_INPUT_UNITS,\n    methodVersion: MATERIAL_DECISION_UNIT_METHOD_VERSION,\n  }\n  const optionalMaterialCeiling = (input.budgetChars ?? MATERIAL_BUDGET_CHARS) * BYTES_PER_BUDGET_CHAR[writingLanguage]\n\n  const select = () => {\n    const choose = (dropped: Set<MaterialCandidate>) => selectChapterSources({\n      current: input.identity,\n      capacity,\n      optionalMaterialCeiling,\n      relevanceTerms: input.relevanceTerms,\n      candidates: candidates.filter(item => !dropped.has(item)),\n    })\n    const covered = (selection: SourceSelection) => {\n      const passages: string[] = []\n      if (selection.decision === 'ready') for (const material of selection.included) {\n        const family = familyBySourceId.get(material.ref.sourceId)\n        if (family?.family === 'finalized') passages.push(...family.passages)\n      }\n      return new Set(referenceCandidates.filter(({ reference }) => reference.deduplicateAgainstFinalized\n        && reference.text.length > 0 && passages.some(passage => passage.includes(reference.text))).map(({ candidate }) => candidate))\n    }\n    const droppedReferences = covered(choose(new Set()))\n    let selection = choose(droppedReferences)\n    while (droppedReferences.size > 0) {\n      const stillCovered = covered(selection)\n      const restored = [...droppedReferences].filter(candidate => !stillCovered.has(candidate))\n      if (!restored.length) break\n      for (const candidate of restored) droppedReferences.delete(candidate)\n      selection = choose(droppedReferences)\n    }\n    return { droppedReferences, selection }\n  }\n  const { selection, droppedReferences } = select()\n  for (const candidate of droppedReferences) {\n    await recordDecisionOmission({\n      sourceId: candidate.ref.sourceId,\n      revision: candidate.ref.revision,\n      contentHash: candidate.ref.contentHash,\n      reason: 'deduplicated-against-finalized',\n      category: candidate.category,\n    })\n  }\n  if (selection.decision !== 'ready') {\n    const omission = selection.omissions.find(item => (\n      [requiredCandidate, requiredPredecessorMaterial].some(material => material\n        && item.sourceId === material.ref.sourceId\n        && item.revision === material.ref.revision\n        && item.contentHash === material.ref.contentHash)\n    ))\n    if (omission) {\n      throw new ChapterMaterialCapacityError({\n        decision: 'capacity-conflict',\n        blockingSourceId: omission.sourceId,\n        blockingReason: omission.reason,\n        omissions: selection.omissions,\n        coverage: selection.coverage,\n      }, writingLanguage)\n    }\n  }\n  if (selection.decision !== 'ready') throw new ChapterMaterialCapacityError(selection, writingLanguage)\n\n  // 渲染：块头沿用各族原有的模板（在构造候选时就已经套好，这里不做二次改写），\n  // 顺序就是合同的顺序——必需材料在前，其后按相关度与规范全序。\n  // 必需材料按**内容哈希**结算覆盖，`ready` 意味着该哈希已被某条 included 材料覆盖，\n  // 所以这里按哈希取回的就是实际进入提示词的那一份（同内容被兄弟来源满足时也一样）。\n  const requiredBlock = requiredCandidate\n    ? selection.included.find(item => item.ref.contentHash === requiredCandidate.ref.contentHash)?.text ?? ''\n    : ''\n  const sourcedBlocks = selection.included\n    .filter(item => item.ref.sourceId !== REQUIRED_SOURCE_ID)\n    .map(item => item.text)\n\n  const selectedOmissions = selection.omissions\n    .map(omission => describeSelectionOmission(omission, familyBySourceId))\n    .filter((omission): omission is ChapterMaterialOmission => omission !== null)\n  const allOmissions = [...omissions, ...selectedOmissions]\n  const gap = allOmissions.length > 0\n    ? promptLanguageText(\n        writingLanguage,\n        `【可选材料覆盖缺口】${allOmissions.map(item => `${item.source}${item.chapterNumber ? `#${item.chapterNumber}` : ''}:${item.reason}`).join('；')}`,\n        `[Optional material coverage gaps] ${allOmissions.map(item => `${item.source}${item.chapterNumber ? `#${item.chapterNumber}` : ''}:${item.reason}`).join('; ')}`,\n      )\n    : ''\n\n  const consumedFinalizedSources: FinalizedMaterialSource[] = []\n  let includedFinalizedFacts = 0\n  for (const material of selection.included) {\n    const family = familyBySourceId.get(material.ref.sourceId)\n    if (family?.family !== 'finalized' || !family.source) continue\n    consumedFinalizedSources.push(family.source)\n    includedFinalizedFacts += family.locatedEvidence\n  }\n\n  return {\n    selection,\n    decision: buildMaterialDecisionReceipt(selection, capacity, decisionOmissions),\n    text: [requiredBlock, sourced, ...sourcedBlocks, gap].filter(Boolean).join('\\n\\n'),\n    previousEnding: requiredPredecessor\n      ? previousChapterEnding(requiredPredecessor.content)\n      : previousChapterEnding(input.finalized.find(source => source.includeEnding)?.content ?? ''),\n    includedFinalizedFacts,\n    consumedFinalizedSources,\n    omissions: allOmissions,\n  }\n}\n\n/**\n * 合同的省略是全域的，这里只投影回装配层的族（并在必要时带上章号）。\n * `author:required` 的省略只出现在容量/拆分决策里，那时调用方已经抛错，不会走到这里。\n */\nfunction describeSelectionOmission(\n  omission: SourceOmission,\n  familyBySourceId: ReadonlyMap<string, MaterialFamily>,\n): ChapterMaterialOmission | null {\n  const family = familyBySourceId.get(omission.sourceId)\n  if (!family || family.family === 'required') return null\n  return {\n    source: family.family,\n    ...(family.chapterNumber === undefined ? {} : { chapterNumber: family.chapterNumber }),\n    reason: SELECTION_OMISSION_REASON[omission.reason],\n  }\n}\n"
    },
    {
      "path": "src/services/workflows/context-snapshot.ts",
      "content": "import type { ContextSnapshot, ProjectEpoch } from '../../shared/source-ref'\nimport { hashAuthorText } from '../../shared/source-ref'\nimport type { SelectedMaterial, SourceSelection } from './source-selection'\n\n/** 估计器版本随快照冻结；单位是包含材料的 UTF-8 字节数。 */\nexport const CONTEXT_ESTIMATOR_VERSION = 'utf8-bytes-v1'\n\nexport interface ChapterContextSnapshotInput {\n  current: ProjectEpoch\n  selection: Extract<SourceSelection, { decision: 'ready' }>\n}\n\n/** 码元比较：不用 localeCompare，避免排序依赖 ICU/locale 或把不同字符串判成相等。 */\nfunction compareCodeUnit(left: string, right: string): number {\n  return left < right ? -1 : left > right ? 1 : 0\n}\n\n/**\n * S01 的槽位只有三种，比类别粗，所以类别另写在 reason 前缀里（`<category>: ...`），\n * 下游必须按 reason 前缀取类别，slot 只作粗归类。\n *\n * `derived-locator` 映射成 `finalized-fact`：stale 定位唯一能进入 included 的东西\n * 是从同一可读定稿回读到的原文，那已是定稿事实，不是「未确认衔接」。\n * `future-plan` 与 `reference` 只作规划性约束，不构成事实。\n */\nconst SLOT_BY_CATEGORY = {\n  author: 'author-constraint',\n  'finalized-history': 'finalized-fact',\n  'future-plan': 'author-constraint',\n  'derived-locator': 'finalized-fact',\n  reference: 'author-constraint',\n} as const\n\nexport function contextSnapshotUnits(entries: readonly SelectedMaterial[]): number {\n  return entries.reduce((sum, entry) => sum + new TextEncoder().encode(entry.text).length, 0)\n}\n\n/**\n * 冻结选择结果 -> 可重放快照。\n *\n * 指纹覆盖真正进入上下文的内容与完整的省略裁决，所以「同一 ref、不同正文」或\n * 「同一来源集、不同省略」都不会撞成同一个 id。会话 epoch 只记不哈希：同一章\n * 跨会话重放得到同一个快照 id。\n *\n * 边界：S01 的 `ContextSnapshot` 是被冻结的共享 DTO，只承载投影结果。必需的\n * coverage、decision 以及候选 state/lineage 留在调用方的 `SourceSelection` 上，\n * 由 S10B 的 receipt 与快照一起持久化，本函数不扩展共享类型。\n *\n * 本函数不读数据库、不写文件、不发请求。\n */\nexport async function buildChapterContextSnapshot(input: ChapterContextSnapshotInput): Promise<ContextSnapshot> {\n  const ordered = [...input.selection.included].sort((left, right) =>\n    compareCodeUnit(left.ref.sourceId, right.ref.sourceId)\n    || compareCodeUnit(left.ref.contentHash, right.ref.contentHash)\n    || compareCodeUnit(left.text, right.text))\n  const omissions = [...input.selection.omissions].sort((left, right) =>\n    compareCodeUnit(left.sourceId, right.sourceId)\n    || left.revision - right.revision\n    || compareCodeUnit(left.contentHash, right.contentHash)\n    || compareCodeUnit(left.reason, right.reason)\n    || Number(left.required) - Number(right.required))\n  const hash = await hashAuthorText(JSON.stringify({\n    included: ordered.map(entry => ({\n      sourceId: entry.ref.sourceId,\n      revision: entry.ref.revision,\n      contentHash: entry.ref.contentHash,\n      category: entry.category,\n      required: entry.required,\n      text: entry.text,\n    })),\n    omissions: omissions.map(omission => ({\n      sourceId: omission.sourceId,\n      revision: omission.revision,\n      contentHash: omission.contentHash,\n      reason: omission.reason,\n      required: omission.required,\n    })),\n  }))\n  return {\n    projectId: input.current.projectId,\n    epoch: input.current.epoch,\n    id: `context:${hash}`,\n    hash,\n    sources: ordered.map(entry => ({\n      ref: entry.ref,\n      slot: SLOT_BY_CATEGORY[entry.category],\n      reason: `${entry.category}: ${entry.reason}`,\n    })),\n    omissions: omissions.map(omission => ({\n      sourceId: omission.sourceId,\n      reason: omission.reason,\n      required: omission.required,\n    })),\n    estimate: { methodVersion: CONTEXT_ESTIMATOR_VERSION, inputUnits: contextSnapshotUnits(ordered) },\n  }\n}\n"
    },
    {
      "path": "electron/services/review-revision-generation.ts",
      "content": "import type Database from 'better-sqlite3'\nimport { randomUUID } from 'node:crypto'\nimport { isDeepStrictEqual } from 'node:util'\nimport type { MainGenerationRunHandle, MainGenerationSnapshot } from '../../src/services/generation/generation-runtime'\nimport type { BeginGenerationRequest } from '../../src/shared/generation-owner-contract'\nimport type { PrepareReviewRevisionRequest, PreparedReviewRevisionContext, ReviewGenerationCommitRequest,\n  RevisionGenerationCommitRequest, ReviewRevisionCommitReceipt, ReviewRevisionContext, ReviewRevisionRecovery } from '../../src/shared/review-revision-generation'\nimport { buildReviewGenerationReport, type ReviewReportVersion } from '../../src/shared/review-generation-report'\nimport { buildReviewCycleRecheckReport, isNoopRevision, recheckCommitPolicy } from '../../src/shared/review-cycle'\nimport { countDraftUnits } from '../../src/shared/draft-units'\nimport { assertMateriallyCompleteRevision } from '../../src/services/workflows/commands/refinement-completeness'\nimport { GenerationRunRepository, textHash, type DurableGenerationRun } from '../repositories/generation-run-repository'\nimport { ReviewRepository } from '../repositories/review-repository'\nimport { RevisionRepository } from '../repositories/revision-repository'\nimport { ReviewCycleRepository } from '../repositories/review-cycle-repository'\nimport { captureReviewRevisionContext, reviewRevisionRequest, REVIEW_REVISION_OPERATIONS } from './review-revision-context'\n\ntype ArtifactRef = ReviewGenerationCommitRequest['artifact']\ninterface Effect {\n  kind: 'review' | 'revision'; id: number; index: number; contentHash: string; contextHash: string\n  artifact: ArtifactRef; compositionHash?: string; reportVersion?: 2\n}\ninterface AttemptRow { attempt_id: string; run_id: string; usage_receipt_json: string }\nconst handleOf = (run: DurableGenerationRun): MainGenerationRunHandle => ({ projectId: run.binding.projectId,\n  epoch: run.binding.epoch, rootActionId: run.rootActionId, runId: run.runId })\nconst contextHash = (context: ReviewRevisionContext) => textHash(JSON.stringify(context))\n\n/** Admission contexts are disposable; recovery and formal-effect truth live in the existing run ledger. */\nexport class ReviewRevisionGeneration {\n  private readonly contexts = new Map<string, PreparedReviewRevisionContext>()\n  constructor(private readonly db: Database.Database, private readonly runs: GenerationRunRepository,\n    private readonly scope: { projectId: string; epoch: string }, private readonly assertCurrent: () => void) {}\n\n  private remember(context: ReviewRevisionContext, lineage: { parentRootActionId?: string; modelId?: string } = {}): PreparedReviewRevisionContext {\n    const prepared = { contextId: randomUUID(), context: structuredClone(context), ...lineage }\n    if (this.contexts.size >= 64) this.contexts.delete(this.contexts.keys().next().value!)\n    this.contexts.set(prepared.contextId, prepared)\n    return structuredClone(prepared)\n  }\n  private context(run: DurableGenerationRun): ReviewRevisionContext {\n    const context = run.binding.sourceManifest.reviewRevisionContext as ReviewRevisionContext | undefined\n    if (!context || context.version !== 1 || context.operation !== run.binding.sourceManifest.operation\n      || !REVIEW_REVISION_OPERATIONS.includes(context.operation)\n      || run.binding.sourceManifest.reviewRevisionContextHash !== contextHash(context)\n      || context.sourceHash !== textHash(context.source.content)\n      || !isDeepStrictEqual(run.binding.sourceManifest.authorInputs, [{ id: 'review-revision-context', text: JSON.stringify(context) }]))\n      throw new Error('GENERATION_REVIEW_CONTEXT_UNPROVEN')\n    return context\n  }\n  private attempts(runId?: string): AttemptRow[] {\n    return (runId ? this.db.prepare('SELECT attempt_id,run_id,usage_receipt_json FROM generation_attempts WHERE run_id=? ORDER BY rowid').all(runId)\n      : this.db.prepare('SELECT attempt_id,run_id,usage_receipt_json FROM generation_attempts ORDER BY rowid').all()) as AttemptRow[]\n  }\n  /** Formal effects seal the proof they reference. Retrying their saved ACK remains read-only. */\n  assertMutable(runId: string): void {\n    if (this.attempts(runId).some(row => JSON.parse(row.usage_receipt_json)?.reviewRevisionEffect))\n      throw new Error('GENERATION_REVIEW_ALREADY_SAVED')\n  }\n  private requireRun(handle: MainGenerationRunHandle): DurableGenerationRun {\n    this.assertCurrent()\n    const run = this.runs.get(handle.runId)\n    if (run.binding.projectId !== this.scope.projectId || !isDeepStrictEqual(handle, handleOf(run))) throw new Error('GENERATION_RUN_IDENTITY_MISMATCH')\n    this.context(run)\n    return run\n  }\n  private proveArtifact(run: DurableGenerationRun, reference: ArtifactRef) {\n    if (!reference || Object.keys(reference).some(key => !['artifactId', 'revision', 'textHash'].includes(key))) throw new Error('GENERATION_REVIEW_ARTIFACT_INVALID')\n    const row = this.db.prepare('SELECT attempt_id,run_id,status FROM generation_artifacts WHERE artifact_id=?').get(reference.artifactId) as { attempt_id: string; run_id: string; status: string } | undefined\n    if (!row || row.run_id !== run.runId || row.status === 'discarded') throw new Error('GENERATION_REVIEW_ARTIFACT_INVALID')\n    const receipt = this.runs.receipt(row.attempt_id), artifact = receipt.artifact\n    if (!artifact || artifact.revision !== reference.revision || artifact.textHash !== reference.textHash\n      || textHash(artifact.text) !== reference.textHash || receipt.failureCode || receipt.result?.finishReason !== 'stop'\n      || !['settled', 'unknown'].includes(receipt.attempt.status)) throw new Error('GENERATION_REVIEW_ARTIFACT_INVALID')\n    return { row, receipt, artifact }\n  }\n  private reviewBody(run: DurableGenerationRun, reference: ArtifactRef, reportVersion: ReviewReportVersion = 2): string {\n    const context = this.context(run), { row, artifact } = this.proveArtifact(run, reference)\n    if (context.recheck) {\n      const attempt = this.attempts(run.runId).find(candidate => candidate.attempt_id === row.attempt_id)\n      let persistedVersion: 1 | 2 | undefined\n      try {\n        const receipt = attempt && JSON.parse(attempt.usage_receipt_json).reviewCycleRecheck\n        if (receipt?.version === 1 || receipt?.version === 2) persistedVersion = receipt.version\n      } catch { /* Invalid persisted receipts fail later proof checks; do not downgrade current policy. */ }\n      const policy = persistedVersion ? { ...context.recheck, version: persistedVersion } : recheckCommitPolicy(context.recheck)\n      const built = buildReviewCycleRecheckReport(artifact.text, context.source.content, policy, context.uiLocale, reportVersion)\n      return JSON.stringify({ summary: built.summary, items: built.items }, null, 2)\n    }\n    return JSON.stringify(buildReviewGenerationReport({ content: artifact.text, sourceContent: context.source.content,\n      frozenGoals: context.frozenGoals, writingLanguage: context.writingLanguage, uiLocale: context.uiLocale,\n      preflightFindings: context.preflightFindings, reportVersion }), null, 2)\n  }\n  private saved(run: DurableGenerationRun): { effect: Effect; receipt: ReviewRevisionCommitReceipt } | undefined {\n    const rows = this.attempts(run.runId).filter(row => JSON.parse(row.usage_receipt_json)?.reviewRevisionEffect)\n    if (rows.length > 1) throw new Error('GENERATION_REVIEW_RECEIPT_INVALID')\n    if (!rows[0]) return undefined\n    const effect = JSON.parse(rows[0].usage_receipt_json).reviewRevisionEffect as Effect\n    const context = this.context(run), proof = this.proveArtifact(run, effect.artifact)\n    if (effect.reportVersion !== undefined && (effect.reportVersion !== 2 || effect.kind !== 'review'))\n      throw new Error('GENERATION_REVIEW_RECEIPT_INVALID')\n    if (proof.row.attempt_id !== rows[0].attempt_id || effect.contextHash !== contextHash(context)\n      || effect.kind !== (context.operation === 'review-chapter' ? 'review' : 'revision')) throw new Error('GENERATION_REVIEW_RECEIPT_INVALID')\n    const row = effect.kind === 'review' ? ReviewRepository.getFull(effect.id, this.db) : RevisionRepository.getFull(effect.id, this.db)\n    const index = row && ('reviewIndex' in row ? row.reviewIndex : row.revisionIndex)\n    const composition = effect.kind === 'revision' ? this.runs.readVisibleComposition(run.runId) : undefined\n    const body = effect.kind === 'review' ? this.reviewBody(run, effect.artifact, effect.reportVersion ?? 1) : composition?.text.trim()\n    if (!row || row.baseDraftId !== context.source.id || index !== effect.index || !isDeepStrictEqual(row.sourceDraft, context.source)\n      || effect.contentHash !== textHash(row.content) || row.content !== body\n      || effect.kind === 'revision' && (composition?.algorithm !== 'visible-append-v1' || composition.textHash !== effect.compositionHash\n        || composition.artifactIds.at(-1) !== effect.artifact.artifactId)) throw new Error('GENERATION_REVIEW_RECEIPT_INVALID')\n    const revisionStatus = 'status' in row ? row.status as ReviewRevisionCommitReceipt['revisionStatus'] : undefined\n    if (revisionStatus && !['pending', 'merged', 'discarded'].includes(revisionStatus)) throw new Error('GENERATION_REVIEW_RECEIPT_INVALID')\n    const cycle = context.recheck ? ReviewCycleRepository.planRecheck(context.recheck.cycleId, this.db) : undefined\n    return { effect, receipt: { success: true, kind: effect.kind, id: row.id, index: effect.index,\n      content: row.content, contentHash: effect.contentHash, source: structuredClone(context.source), ...(revisionStatus ? { revisionStatus } : {}),\n      ...(context.recheck ? { reviewCycle: { cycleId: context.recheck.cycleId, revisionStatus: 'merge-committed',\n        recheckCount: cycle?.disposition === 'completed' ? 1 : 0, disposition: cycle?.disposition ?? 'required' } } : {}) } }\n  }\n  private parent(context: ReviewRevisionContext): { parentRootActionId?: string; modelId?: string } {\n    if (context.recheck) {\n      const plan = ReviewCycleRepository.planRecheck(context.recheck.cycleId, this.db)\n      const frozenPlan = plan.context && { ...plan.context, version: context.recheck.version }\n      if (plan.disposition !== 'required' || !frozenPlan || !isDeepStrictEqual(frozenPlan, context.recheck))\n        throw new Error('GENERATION_REVIEW_LINEAGE_UNPROVEN')\n      const matching = this.attempts().filter(row => {\n        const effect = JSON.parse(row.usage_receipt_json)?.reviewRevisionEffect as Effect | undefined\n        return effect?.kind === 'review' && effect.id === plan.reviewId\n      })\n      if (matching.length !== 1) throw new Error('GENERATION_REVIEW_LINEAGE_UNPROVEN')\n      const parentRun = this.runs.get(matching[0]!.run_id)\n      if (parentRun.rootActionId !== plan.rootActionId || parentRun.binding.projectId !== this.scope.projectId)\n        throw new Error('GENERATION_REVIEW_LINEAGE_UNPROVEN')\n      return { parentRootActionId: plan.rootActionId,\n        modelId: (parentRun.binding.sourceManifest.modelReceipt as { modelId: string }).modelId }\n    }\n    if (!context.confirmation) return {}\n    const matching = this.attempts().filter(row => {\n      const effect = JSON.parse(row.usage_receipt_json)?.reviewRevisionEffect as Effect | undefined\n      return effect?.kind === 'review' && effect.id === context.confirmation!.snapshot.sourceReviewId\n    })\n    if (matching.length !== 1) throw new Error('GENERATION_REVIEW_LINEAGE_UNPROVEN')\n    const run = this.runs.get(matching[0]!.run_id), saved = this.saved(run)\n    if (run.binding.projectId !== this.scope.projectId || !saved || saved.receipt.kind !== 'review'\n      || saved.receipt.contentHash !== context.confirmation.originalReviewContentHash\n      || !isDeepStrictEqual(saved.receipt.source, context.source)) throw new Error('GENERATION_REVIEW_LINEAGE_UNPROVEN')\n    return { parentRootActionId: run.rootActionId, modelId: (run.binding.sourceManifest.modelReceipt as { modelId: string }).modelId }\n  }\n  prepare(request: PrepareReviewRevisionRequest): PreparedReviewRevisionContext {\n    this.assertCurrent()\n    return this.db.transaction(() => {\n      const context = captureReviewRevisionContext(this.db, request, this.scope.projectId)\n      return this.remember(context, this.parent(context))\n    })()\n  }\n  admit(selection: BeginGenerationRequest): PreparedReviewRevisionContext | undefined {\n    this.assertCurrent()\n    if (!REVIEW_REVISION_OPERATIONS.includes(selection.operation as ReviewRevisionContext['operation'])) {\n      if (selection.reviewRevisionContextId) throw new Error('GENERATION_REVIEW_CONTEXT_INVALID')\n      return undefined\n    }\n    const prepared = selection.reviewRevisionContextId && this.contexts.get(selection.reviewRevisionContextId)\n    if (!prepared) throw new Error('GENERATION_REVIEW_CONTEXT_REQUIRED')\n    const { context } = prepared, finalized = context.source.status === 'finalized'\n    const prompt = context.operation === 'review-chapter' ? 'consistency_check' : context.operation === 'refine-draft' ? 'refine_chapter' : 'refine_from_review'\n    if (selection.operation !== context.operation || selection.chapterNumber !== context.source.chapterNumber\n      || !isDeepStrictEqual(selection.promptKeys, [prompt]) || !isDeepStrictEqual(selection.skillStages, [context.operation === 'review-chapter' ? 'review' : 'refinement'])\n      || selection.outputOverrides !== undefined || selection.batchId !== undefined || selection.continueDirectoryOperationId !== undefined\n      || selection.output !== (context.operation === 'review-chapter' ? 'structured-data' : 'visible-text')\n      || !isDeepStrictEqual(selection.selectedDraftIds, finalized ? [] : [context.source.id])\n      || !isDeepStrictEqual(selection.selectedFinalizedDraftIds, finalized ? [context.source.id] : [])\n      || !isDeepStrictEqual(selection.authorInputs, [{ id: 'review-revision-context', text: JSON.stringify(context) }])\n      || (prepared.parentRootActionId !== undefined && selection.parentRootActionId !== prepared.parentRootActionId)\n      || (prepared.parentRootActionId === undefined && selection.parentRootActionId !== undefined)\n      // The confirmed review proves lineage, not the model choice of a new revision stage.\n      || !context.confirmation && prepared.modelId && selection.modelId !== prepared.modelId) throw new Error('GENERATION_REVIEW_CONTEXT_MISMATCH')\n    if (!isDeepStrictEqual(context, captureReviewRevisionContext(this.db, reviewRevisionRequest(context), this.scope.projectId,\n      context.recheck?.version))\n      || !isDeepStrictEqual(this.parent(context), prepared.parentRootActionId ? { parentRootActionId: prepared.parentRootActionId, modelId: prepared.modelId } : {}))\n      throw new Error('GENERATION_REVIEW_CONTEXT_CHANGED')\n    return structuredClone(prepared)\n  }\n  private assertPrepared(contextId: string, run: DurableGenerationRun): void {\n    if (!isDeepStrictEqual(this.contexts.get(contextId)?.context, this.context(run))) throw new Error('GENERATION_REVIEW_CONTEXT_REQUIRED')\n  }\n  private record(run: DurableGenerationRun, artifact: ArtifactRef, effect: Omit<Effect, 'artifact' | 'contextHash'>): ReviewRevisionCommitReceipt {\n    const proof = this.proveArtifact(run, artifact), row = this.attempts(run.runId).find(row => row.attempt_id === proof.row.attempt_id)!\n    const usage = JSON.parse(row.usage_receipt_json)\n    this.db.prepare('UPDATE generation_attempts SET usage_receipt_json=? WHERE attempt_id=?').run(JSON.stringify({ ...usage,\n      reviewRevisionEffect: { ...effect, artifact, contextHash: contextHash(this.context(run)) } }), row.attempt_id)\n    return this.saved(run)!.receipt\n  }\n  commitReview(request: ReviewGenerationCommitRequest, assertSources: (handle: MainGenerationRunHandle) => void): ReviewRevisionCommitReceipt {\n    if (!request || Object.keys(request).some(key => !['contextId', 'handle', 'artifact'].includes(key))) throw new Error('GENERATION_REVIEW_COMMIT_INVALID')\n    return this.db.transaction(() => {\n      const run = this.requireRun(request.handle), context = this.context(run), saved = this.saved(run)\n      if (context.operation !== 'review-chapter') throw new Error('GENERATION_REVIEW_COMMIT_INVALID')\n      if (saved) {\n        if (!isDeepStrictEqual(saved.effect.artifact, request.artifact)) throw new Error('GENERATION_REVIEW_COMMIT_CONFLICT')\n        return saved.receipt\n      }\n      this.assertPrepared(request.contextId, run); assertSources(request.handle)\n      const proof = this.proveArtifact(run, request.artifact)\n      const content = this.reviewBody(run, request.artifact)\n      const result = ReviewRepository.create({ baseDraftId: context.source.id, content, expectedSource: context.source }, this.db)\n      const contentHash = textHash(content)\n      const receipt = this.record(run, request.artifact, { kind: 'review', id: result.id, index: result.reviewIndex, contentHash,\n        reportVersion: 2 })\n      if (context.recheck) {\n        const policy = recheckCommitPolicy(context.recheck)\n        const built = buildReviewCycleRecheckReport(proof.artifact.text, context.source.content, policy, context.uiLocale)\n        const findings = built.decisions.filter(decision => decision.status !== 'unknown').map(decision => {\n          const item = built.items[decision.reviewItemIndex]!\n          const resolved = decision.status === 'resolved'\n          return { findingId: decision.findingId, targetId: decision.targetId, reviewItemIndex: decision.reviewItemIndex,\n            evidenceHash: textHash(JSON.stringify({ findingId: decision.findingId, targetId: decision.targetId,\n              reviewItemIndex: decision.reviewItemIndex, item, resolved })), resolved }\n        })\n        const attempt = this.attempts(run.runId).find(row => row.attempt_id === proof.row.attempt_id)\n        if (!attempt) throw new Error('GENERATION_REVIEW_RECEIPT_INVALID')\n        const usage = JSON.parse(attempt.usage_receipt_json)\n        this.db.prepare('UPDATE generation_attempts SET usage_receipt_json=? WHERE attempt_id=?').run(JSON.stringify({ ...usage,\n          reviewCycleRecheck: { version: policy.version, cycleId: context.recheck.cycleId,\n            comparisonVersion: context.recheck.comparisonVersion, mergedHash: context.recheck.mergedHash,\n            findingSetHash: context.recheck.findingSetHash, findings } }), attempt.attempt_id)\n        ReviewCycleRepository.commitRecheck(context.recheck.cycleId, attempt.attempt_id, this.db)\n        return this.saved(run)!.receipt\n      }\n      ReviewCycleRepository.create({ rootActionId: run.rootActionId, reviewId: result.id, reviewContentHash: contentHash,\n        source: { projectId: run.binding.projectId, epoch: run.binding.epoch, sourceId: `draft:${context.source.id}`,\n          revision: context.source.version, contentHash: textHash(context.source.content) } }, this.db)\n      return receipt\n    }).immediate()\n  }\n  commitRevision(request: RevisionGenerationCommitRequest, assertSources: (handle: MainGenerationRunHandle) => void): ReviewRevisionCommitReceipt {\n    if (!request || Object.keys(request).some(key => !['contextId', 'handle', 'expectedCompositionHash'].includes(key))) throw new Error('GENERATION_REVIEW_COMMIT_INVALID')\n    return this.db.transaction(() => {\n      const run = this.requireRun(request.handle), context = this.context(run), saved = this.saved(run)\n      if (context.operation === 'review-chapter') throw new Error('GENERATION_REVIEW_COMMIT_INVALID')\n      if (saved) {\n        if (saved.effect.compositionHash !== request.expectedCompositionHash) throw new Error('GENERATION_REVIEW_COMMIT_CONFLICT')\n        return saved.receipt\n      }\n      this.assertPrepared(request.contextId, run); assertSources(request.handle)\n      const composition = this.runs.readVisibleComposition(run.runId)\n      if (!composition || composition.algorithm !== 'visible-append-v1' || composition.textHash !== request.expectedCompositionHash)\n        throw new Error('GENERATION_REVIEW_COMPOSITION_REQUIRED')\n      const artifact = composition.sources.at(-1)!\n      this.proveArtifact(run, artifact)\n      const content = composition.text.trim()\n      if (!content) throw new Error('GENERATION_REVIEW_REVISION_EMPTY')\n      assertMateriallyCompleteRevision(context.source.content, content, context.config.wordsPerChapter, context.uiLocale)\n      if (isNoopRevision(context.source.content, content)) throw new Error('GENERATION_REVIEW_REVISION_NOOP')\n      const result = RevisionRepository.replacePending({ baseDraftId: context.source.id,\n        revisionType: context.operation === 'refine-from-review' ? 'review-fix' : 'refine',\n        ...(context.confirmation ? { reviewSourceId: context.confirmation.reviewSourceId } : {}),\n        userPrompt: context.confirmation?.snapshot.authorGuidance ?? context.authorInputs.find(item => item.id === 'user-prompt')?.text ?? '',\n        content, wordCount: countDraftUnits(content), expectedSource: context.source }, this.db)\n      const receipt = this.record(run, artifact, { kind: 'revision', id: result.id, index: result.revisionIndex,\n        contentHash: textHash(content), compositionHash: composition.textHash })\n      if (context.confirmation) {\n        const cycle = this.db.prepare('SELECT cycle_id,root_action_id FROM review_cycles WHERE review_id=?')\n          .get(context.confirmation.snapshot.sourceReviewId) as { cycle_id: string; root_action_id: string } | undefined\n        if (!cycle) throw new Error('REVIEW_CYCLE_INPUT_INVALID')\n        ReviewCycleRepository.attachGeneratedRevision({ cycleId: cycle.cycle_id, rootActionId: cycle.root_action_id,\n          confirmationReviewId: context.confirmation.reviewSourceId,\n          confirmationContentHash: textHash(context.confirmation.content), revisionId: result.id,\n          revisionContentHash: textHash(content) }, this.db)\n      }\n      return receipt\n    }).immediate()\n  }\n  readRecovery(handle: MainGenerationRunHandle, sourcesMatch: (run: DurableGenerationRun) => boolean,\n    snapshot: (run: DurableGenerationRun) => MainGenerationSnapshot | undefined): ReviewRevisionRecovery {\n    const run = this.requireRun(handle), context = this.context(run), saved = this.saved(run)?.receipt\n    let current = false\n    try { current = sourcesMatch(run) } catch { /* Original candidate remains available when a source/model/template has changed. */ }\n    const composition = this.runs.readVisibleComposition(run.runId) ?? undefined, latestArtifact = snapshot(run)\n    const last = composition?.artifactIds.at(-1)\n    const finish = (id: string | undefined) => {\n      const attempt = id && this.db.prepare('SELECT attempt_id FROM generation_artifacts WHERE artifact_id=?').pluck().get(id) as string | undefined\n      return attempt ? this.runs.receipt(attempt).result?.finishReason ?? null : null\n    }\n    const lastCompositionFinishReason = finish(last), latestArtifactFinishReason = finish(latestArtifact?.artifactId)\n    const attemptedPurposes = this.attempts(run.runId).map(row => JSON.parse(row.usage_receipt_json).purpose ?? 'unknown')\n    let canResume = current\n    if (!saved && context.operation === 'review-chapter' && latestArtifactFinishReason === 'length'\n      && attemptedPurposes.filter(purpose => purpose === 'review-chapter').length >= 2\n      && !attemptedPurposes.includes('review-chapter-rebuild')) canResume = false\n    if (!saved && context.operation !== 'review-chapter' && composition && lastCompositionFinishReason === 'stop') {\n      try {\n        assertMateriallyCompleteRevision(context.source.content, composition.text, context.config.wordsPerChapter, context.uiLocale)\n        if (isNoopRevision(context.source.content, composition.text.trim())) canResume = false\n      } catch { canResume = false }\n    }\n    return { handle: handleOf(run), context: structuredClone(context), modelId: (run.binding.sourceManifest.modelReceipt as { modelId: string }).modelId,\n      sourceStatus: current ? 'current' : 'conflict', canResume, ...(saved ? { saved } : {}),\n      ...(canResume && !saved ? { contextId: this.remember(context, this.parent(context)).contextId } : {}), ...(composition ? { composition } : {}),\n      lastCompositionFinishReason, ...(latestArtifact ? { latestArtifact, latestArtifactFinishReason } : {}), attemptedPurposes }\n  }\n  close(): void { this.contexts.clear() }\n}\n"
    },
    {
      "path": "electron/services/finalization-service.ts",
      "content": "import { createHash, randomUUID } from 'node:crypto'\n\nimport {\n  FinalizationRepository,\n  type FinalizationRecord,\n  type PublicationStatus,\n} from '../repositories/finalization-repository'\nimport {\n  manuscriptPublisher,\n  resolveManuscriptTarget,\n  type PublishManuscriptInput,\n} from './manuscript-publisher'\nimport { PortableRuntimeFreezeError, readPortableRuntimeFreeze } from './portable-runtime-freeze'\n\nexport interface FinalizationRequest {\n  /** 已由 ProjectAccess 验证并 canonicalize 的项目根目录。 */\n  projectRoot: string\n  draftId: number\n  chapterNumber: number\n  chapterTitle: string\n  content: string\n  contentRevision: number\n}\n\nexport interface FinalizationRetryRequest {\n  /** 已由 ProjectAccess 验证并 canonicalize 的项目根目录。 */\n  projectRoot: string\n  finalizationId: string\n}\n\nexport interface FinalizationResult {\n  success: boolean\n  /** false 代表数据库事务从未提交；true 则数据库定稿事实已存在。 */\n  committed: boolean\n  finalizationId?: string\n  contentHash?: string\n  contentRevision?: number\n  draftId?: number\n  publicationStatus?: PublicationStatus\n  error?: string\n}\n\nexport interface FinalizationPublisher {\n  publish(input: PublishManuscriptInput): Promise<void>\n}\n\nexport interface FinalizationServiceOptions {\n  createFinalizationId?: () => string\n  publisher?: FinalizationPublisher\n}\n\nfunction toResult(record: FinalizationRecord, success: boolean, error?: string): FinalizationResult {\n  return {\n    success,\n    committed: true,\n    finalizationId: record.finalizationId,\n    contentHash: record.contentHash,\n    contentRevision: record.contentRevision,\n    draftId: record.draftId,\n    publicationStatus: record.publicationStatus,\n    ...(error ? { error } : {}),\n  }\n}\n\nfunction snapshotHash(content: string): string {\n  return createHash('sha256').update(content, 'utf8').digest('hex')\n}\n\nfunction hasSameFrozenRequest(\n  record: FinalizationRecord,\n  request: FinalizationRequest,\n  contentHash: string,\n): boolean {\n  return record.draftId === request.draftId\n    && record.chapterNumber === request.chapterNumber\n    && record.chapterTitle === request.chapterTitle\n    && record.contentRevision === request.contentRevision\n    && record.contentHash === contentHash\n    && record.contentSnapshot === request.content\n}\n\nfunction snapshotIntegrityError(record: FinalizationRecord): string | null {\n  return snapshotHash(record.contentSnapshot) === record.contentHash\n    ? null\n    : 'FINALIZATION_SNAPSHOT_HASH_MISMATCH'\n}\n\n/**\n * 主进程定稿应用服务：SQLite transaction 是事实源，实体稿仅为可恢复投影。\n * retry 只接收 finalizationId，正文、标题和目标文件名都只从已提交 outbox 读取。\n */\nexport class FinalizationService {\n  private readonly createFinalizationId: () => string\n  private readonly publisher: FinalizationPublisher\n\n  constructor(options: FinalizationServiceOptions = {}) {\n    this.createFinalizationId = options.createFinalizationId ?? randomUUID\n    this.publisher = options.publisher ?? manuscriptPublisher\n  }\n\n  async finalize(request: FinalizationRequest): Promise<FinalizationResult> {\n    const finalizationId = this.createFinalizationId()\n    const contentHash = snapshotHash(request.content)\n    let record: FinalizationRecord\n    try {\n      const existing = FinalizationRepository.getByDraftId(request.draftId)\n      if (existing) {\n        if (!hasSameFrozenRequest(existing, request, contentHash)) {\n          return {\n            success: false,\n            committed: false,\n            error: 'FINALIZATION_COMMIT_CONFLICT',\n          }\n        }\n        // 上次响应可能在客户端收到前丢失。复用既有 finalizationId 与目标文件名，\n        // 而不是因新的 UUID 或文件碰撞创建第二次提交。\n        return this.publishCommitted(request.projectRoot, existing)\n      }\n      const target = resolveManuscriptTarget({\n        projectRoot: request.projectRoot,\n        chapterNumber: request.chapterNumber,\n        chapterTitle: request.chapterTitle,\n        finalizationId,\n      })\n      record = FinalizationRepository.commit({\n        finalizationId,\n        draftId: request.draftId,\n        chapterNumber: request.chapterNumber,\n        chapterTitle: request.chapterTitle,\n        content: request.content,\n        contentHash,\n        contentRevision: request.contentRevision,\n        targetFileName: target.fileName,\n      })\n    } catch (error) {\n      return {\n        success: false,\n        committed: false,\n        finalizationId,\n        contentHash,\n        contentRevision: request.contentRevision,\n        draftId: request.draftId,\n        error: String(error),\n      }\n    }\n    return this.publishCommitted(request.projectRoot, record)\n  }\n\n  async retry(request: FinalizationRetryRequest): Promise<FinalizationResult> {\n    let record: FinalizationRecord | null\n    try {\n      record = FinalizationRepository.get(request.finalizationId)\n    } catch (error) {\n      return { success: false, committed: false, error: String(error) }\n    }\n    if (!record) {\n      return {\n        success: false,\n        committed: false,\n        finalizationId: request.finalizationId,\n        error: 'FINALIZATION_COMMIT_NOT_FOUND',\n      }\n    }\n    const integrityError = snapshotIntegrityError(record)\n    if (integrityError) {\n      return toResult(record, false, integrityError)\n    }\n    if (record.publicationStatus === 'published') {\n      return toResult(record, true)\n    }\n    return this.publishCommitted(request.projectRoot, record)\n  }\n\n  private async publishCommitted(projectRoot: string, record: FinalizationRecord): Promise<FinalizationResult> {\n    try {\n      readPortableRuntimeFreeze(projectRoot).assertMutable('finalization_outbox', record.finalizationId)\n    } catch (error) {\n      const message = error instanceof PortableRuntimeFreezeError ? error.code : String(error)\n      return toResult(record, false, message)\n    }\n    try {\n      const integrityError = snapshotIntegrityError(record)\n      if (integrityError) throw new Error(integrityError)\n      if (record.publicationStatus === 'published') {\n        return toResult(record, true)\n      }\n      if (!FinalizationRepository.isAuthoritative(record.draftId)) {\n        return toResult(record, false, 'FINALIZATION_SUPERSEDED')\n      }\n      await this.publisher.publish({\n        projectRoot,\n        targetFileName: record.targetFileName,\n        chapterNumber: record.chapterNumber,\n        chapterTitle: record.chapterTitle,\n        content: record.contentSnapshot,\n      })\n      return toResult(FinalizationRepository.markPublished(record.finalizationId), true)\n    } catch (error) {\n      // committed: true 已表明定稿已提交、实体稿待发布，各显示处自己写这句；error 只带原因（错误码或系统报错）。\n      const message = String(error)\n      try {\n        const pending = FinalizationRepository.markPublicationPending(record.finalizationId, message)\n        return toResult(pending, false, message)\n      } catch (markError) {\n        // outbox 在事务内已经以 pending 创建；即使补记错误失败，也不能把已提交事实伪装为回滚。\n        console.error('[finalization] 实体稿待发布状态记录失败:', markError)\n        return toResult(record, false, message)\n      }\n    }\n  }\n}\n"
    },
