      "path": "electron/repositories/finalization-repository.ts",
      "content": "import { createHash } from 'node:crypto'\nimport { getCurrentProjectPath, getProjectDb } from '../database'\nimport { readPortableRuntimeFreeze } from '../services/portable-runtime-freeze'\nimport { countDraftUnits } from '../../src/shared/draft-units'\nimport type { DuplicateFinalizationRepair, RepairedDuplicateChapter } from '../../src/shared/finalization-repair'\nimport { freezeFinalizedCharacterSnapshot, invalidateContinuityProjectionFrom } from './summary-repository'\n\nexport type PublicationStatus = 'pending' | 'published'\n\nexport interface FinalizationCommitInput {\n  finalizationId: string\n  draftId: number\n  chapterNumber: number\n  chapterTitle: string\n  content: string\n  contentHash: string\n  contentRevision: number\n  targetFileName: string\n}\n\nexport interface FinalizationRecord {\n  finalizationId: string\n  draftId: number\n  chapterNumber: number\n  chapterTitle: string\n  /** outbox 内冻结的不可变正文；发布和重试绝不回读 contents.body。 */\n  contentSnapshot: string\n  contentHash: string\n  contentRevision: number\n  targetFileName: string\n  knowledgeDocumentId: string\n  publicationStatus: PublicationStatus\n  lastError: string\n  publishedAt: string | null\n}\n\ninterface FinalizationRow {\n  finalization_id: string\n  draft_id: number\n  chapter_number: number\n  chapter_title: string\n  content_hash: string\n  content_revision: number\n  target_file_name: string\n  knowledge_document_id: string\n  publication_status: PublicationStatus\n  last_error: string\n  published_at: string | null\n  content_snapshot: string\n}\n\nexport interface FinalizedDraftExportSnapshot {\n  draftId: number\n  chapterNumber: number\n  version: number\n  title: string\n  content: string\n  finalizationId: string | null\n  contentHash: string\n}\n\nexport type FinalizedDraftExportAuthorityReceipt = ReadonlyArray<Readonly<{\n  draftId: number\n  chapterNumber: number\n  version: number\n  finalizationId: string | null\n  contentHash: string\n}>>\n\ninterface FinalizedDraftExportRow {\n  draft_id: number\n  chapter_number: number\n  version: number\n  body: string\n  finalization_id: string | null\n  outbox_chapter_number: number | null\n  chapter_title: string | null\n  content_hash: string | null\n  content_snapshot: string | null\n}\n\ninterface AuthoritativeFinalizedDraftExport {\n  snapshot: FinalizedDraftExportSnapshot\n  receipt: FinalizedDraftExportAuthorityReceipt[number]\n}\n\nfunction rowToRecord(row: FinalizationRow): FinalizationRecord {\n  return {\n    finalizationId: row.finalization_id,\n    draftId: row.draft_id,\n    chapterNumber: row.chapter_number,\n    chapterTitle: row.chapter_title,\n    contentSnapshot: row.content_snapshot ?? '',\n    contentHash: row.content_hash,\n    contentRevision: row.content_revision,\n    targetFileName: row.target_file_name,\n    knowledgeDocumentId: row.knowledge_document_id ?? '',\n    publicationStatus: row.publication_status,\n    lastError: row.last_error ?? '',\n    publishedAt: row.published_at ?? null,\n  }\n}\n\nfunction requireDatabase() {\n  const db = getProjectDb()\n  if (!db) throw new Error('PROJECT_NOT_OPEN')\n  return db\n}\n\nfunction hasSameFinalizationInput(\n  existing: FinalizationRow,\n  input: FinalizationCommitInput,\n): boolean {\n  return existing.draft_id === input.draftId\n    && existing.chapter_number === input.chapterNumber\n    && existing.chapter_title === input.chapterTitle\n    && existing.content_hash === input.contentHash\n    && existing.content_revision === input.contentRevision\n    && existing.content_snapshot === input.content\n}\n\nfunction selectAuthoritativeExportRows(\n  rows: readonly FinalizedDraftExportRow[],\n): AuthoritativeFinalizedDraftExport[] {\n  const selected: AuthoritativeFinalizedDraftExport[] = []\n  const selectedVersions = new Map<number, number>()\n  for (const row of rows) {\n    const selectedVersion = selectedVersions.get(row.chapter_number)\n    if (selectedVersion !== undefined) {\n      if (selectedVersion === row.version) {\n        throw new Error('FINALIZATION_EXPORT_DUPLICATE_CHAPTER')\n      }\n      continue\n    }\n    if (\n      !Number.isSafeInteger(row.draft_id) || row.draft_id < 1\n      || !Number.isSafeInteger(row.chapter_number) || row.chapter_number < 1\n      || !Number.isSafeInteger(row.version) || row.version < 1\n    ) throw new Error('FINALIZATION_EXPORT_SNAPSHOT_INVALID')\n    if (typeof row.body !== 'string' || row.body.trim().length === 0) {\n      throw new Error('FINALIZATION_EXPORT_CONTENT_EMPTY')\n    }\n\n    const contentHash = createHash('sha256').update(row.body, 'utf8').digest('hex')\n    if (row.finalization_id !== null) {\n      if (typeof row.finalization_id !== 'string' || row.finalization_id.trim().length === 0) {\n        throw new Error('FINALIZATION_EXPORT_SNAPSHOT_INVALID')\n      }\n      if (row.outbox_chapter_number !== row.chapter_number) {\n        throw new Error('FINALIZATION_EXPORT_IDENTITY_MISMATCH')\n      }\n      if (row.content_snapshot !== row.body) {\n        throw new Error('FINALIZATION_EXPORT_CONTENT_MISMATCH')\n      }\n      if (row.content_hash !== contentHash) {\n        throw new Error('FINALIZATION_EXPORT_SUMMARY_MISMATCH')\n      }\n    }\n\n    selectedVersions.set(row.chapter_number, row.version)\n    const authority = {\n      draftId: row.draft_id,\n      chapterNumber: row.chapter_number,\n      version: row.version,\n      finalizationId: row.finalization_id,\n      contentHash,\n    }\n    selected.push({\n      receipt: authority,\n      snapshot: {\n        ...authority,\n        title: row.chapter_title?.trim() ?? '',\n        content: row.body,\n      },\n    })\n  }\n  return selected\n}\n\nconst AUTHORITATIVE_FINALIZED_ORDER = 'drafts.chapter_number ASC, drafts.version DESC, drafts.id DESC'\n\nfunction readAuthoritativeExportRows(): AuthoritativeFinalizedDraftExport[] {\n  const db = requireDatabase()\n  return db.transaction(() => selectAuthoritativeExportRows(db.prepare(`\n    SELECT drafts.id AS draft_id, drafts.chapter_number, drafts.version,\n           contents.body, finalization_outbox.finalization_id,\n           finalization_outbox.chapter_number AS outbox_chapter_number,\n           finalization_outbox.chapter_title, finalization_outbox.content_hash,\n           finalization_outbox.content_snapshot\n    FROM drafts\n    JOIN contents ON contents.id = drafts.content_id\n    LEFT JOIN finalization_outbox ON finalization_outbox.draft_id = drafts.id\n    WHERE drafts.status = 'finalized'\n    ORDER BY ${AUTHORITATIVE_FINALIZED_ORDER}\n  `).all() as FinalizedDraftExportRow[]))()\n}\n\n/**\n * 定稿的数据库事实源。正文、字数、定稿状态与发布 outbox 必须由同一个 SQLite\n * transaction 共同提交；任何一个 statement 失败都会回滚其余变化。\n */\nexport class FinalizationRepository {\n  /** One transactionally frozen, highest-version finalized fact per chapter. */\n  static listAuthoritativeForExport(): FinalizedDraftExportSnapshot[] {\n    return readAuthoritativeExportRows().map(({ snapshot }) => snapshot)\n  }\n\n  static matchesAuthoritativeExportReceipt(receipt: FinalizedDraftExportAuthorityReceipt): boolean {\n    if (!Array.isArray(receipt)) return false\n    const seenChapters = new Set<number>()\n    for (const item of receipt) {\n      if (\n        !item || typeof item !== 'object'\n        || !Number.isSafeInteger(item.draftId) || item.draftId < 1\n        || !Number.isSafeInteger(item.chapterNumber) || item.chapterNumber < 1\n        || !Number.isSafeInteger(item.version) || item.version < 1\n        || !(item.finalizationId === null\n          || (typeof item.finalizationId === 'string' && item.finalizationId.trim().length > 0))\n        || typeof item.contentHash !== 'string' || !/^[a-f0-9]{64}$/u.test(item.contentHash)\n        || seenChapters.has(item.chapterNumber)\n      ) return false\n      seenChapters.add(item.chapterNumber)\n    }\n\n    try {\n      const current = readAuthoritativeExportRows().map(({ receipt: item }) => item)\n      return current.length === receipt.length && current.every((item, index) => (\n        item.draftId === receipt[index]?.draftId\n        && item.chapterNumber === receipt[index]?.chapterNumber\n        && item.version === receipt[index]?.version\n        && item.finalizationId === receipt[index]?.finalizationId\n        && item.contentHash === receipt[index]?.contentHash\n      ))\n    } catch {\n      return false\n    }\n  }\n\n  static commit(input: FinalizationCommitInput): FinalizationRecord {\n    const db = requireDatabase()\n    const transaction = db.transaction(() => {\n      const existing = db.prepare(`\n        SELECT * FROM finalization_outbox WHERE draft_id = ?\n      `).get(input.draftId) as FinalizationRow | undefined\n      if (existing) {\n        // renderer 可能在主进程已提交而响应丢失后重发同一冻结快照。此时新生成的\n        // finalizationId/碰撞候选文件名都不能破坏幂等性，必须返回原提交。\n        if (hasSameFinalizationInput(existing, input)) {\n          return rowToRecord(existing)\n        }\n        throw new Error('FINALIZATION_COMMIT_CONFLICT')\n      }\n\n      const draft = db.prepare(`\n        SELECT id, chapter_number, status, content_id FROM drafts WHERE id = ?\n      `).get(input.draftId) as {\n        id: number\n        chapter_number: number\n        status: string\n        content_id: number\n      } | undefined\n      if (!draft) throw new Error('DRAFT_NOT_FOUND')\n      if (draft.chapter_number !== input.chapterNumber) {\n        throw new Error('FINALIZATION_COMMIT_CHAPTER_MISMATCH')\n      }\n      if (draft.status === 'finalized') {\n        throw new Error('FINALIZATION_COMMIT_OUTBOX_MISSING')\n      }\n      if (draft.status === 'superseded') {\n        throw new Error('FINALIZATION_COMMIT_SUPERSEDED')\n      }\n\n      const replaced = db.prepare(`\n        UPDATE drafts SET status = 'superseded', updated_at = datetime('now')\n        WHERE chapter_number = ? AND status = 'finalized' AND id <> ?\n      `).run(input.chapterNumber, input.draftId)\n      if (replaced.changes > 0) invalidateContinuityProjectionFrom(db, input.chapterNumber)\n\n      db.prepare('UPDATE contents SET body = ? WHERE id = ?')\n        .run(input.content, draft.content_id)\n      db.prepare(`\n        UPDATE drafts\n        SET status = 'finalized', word_count = ?, updated_at = datetime('now')\n        WHERE id = ?\n      `).run(countDraftUnits(input.content), input.draftId)\n      db.prepare(`\n        INSERT INTO finalization_outbox (\n          finalization_id, draft_id, chapter_number, chapter_title,\n          content_hash, content_revision, content_snapshot, target_file_name, publication_status,\n          last_error\n        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', '')\n      `).run(\n        input.finalizationId,\n        input.draftId,\n        input.chapterNumber,\n        input.chapterTitle,\n        input.contentHash,\n        input.contentRevision,\n        input.content,\n        input.targetFileName,\n      )\n      freezeFinalizedCharacterSnapshot(db, { draftId: input.draftId, finalizationId: input.finalizationId,\n        chapterNumber: input.chapterNumber, contentHash: input.contentHash })\n\n      return {\n        finalizationId: input.finalizationId,\n        draftId: input.draftId,\n        chapterNumber: input.chapterNumber,\n        chapterTitle: input.chapterTitle,\n        contentSnapshot: input.content,\n        contentHash: input.contentHash,\n        contentRevision: input.contentRevision,\n        targetFileName: input.targetFileName,\n        knowledgeDocumentId: '',\n        publicationStatus: 'pending' as const,\n        lastError: '',\n        publishedAt: null,\n      }\n    })\n    return transaction()\n  }\n\n  static repairDuplicateFinalizations(): DuplicateFinalizationRepair {\n    const db = requireDatabase()\n    return db.transaction(() => {\n      const rows = db.prepare(`\n        SELECT drafts.id, drafts.chapter_number, drafts.version,\n               finalization_outbox.knowledge_document_id, finalization_outbox.target_file_name,\n               finalization_outbox.publication_status\n        FROM drafts\n        LEFT JOIN finalization_outbox ON finalization_outbox.draft_id = drafts.id\n        WHERE drafts.status = 'finalized' AND drafts.chapter_number IN (\n          SELECT chapter_number FROM drafts WHERE status = 'finalized'\n          GROUP BY chapter_number HAVING COUNT(*) > 1\n        )\n        ORDER BY ${AUTHORITATIVE_FINALIZED_ORDER}\n      `).all() as Array<{\n        id: number\n        chapter_number: number\n        version: number\n        knowledge_document_id: string | null\n        target_file_name: string | null\n        publication_status: string | null\n      }>\n      const chapters: RepairedDuplicateChapter[] = []\n      let keptFileName = ''\n      const supersede = db.prepare(`\n        UPDATE drafts SET status = 'superseded', updated_at = datetime('now')\n        WHERE id = ? AND status = 'finalized'\n      `)\n      for (const row of rows) {\n        const current = chapters.at(-1)\n        if (current?.chapterNumber !== row.chapter_number) {\n          chapters.push({ chapterNumber: row.chapter_number, keptDraftId: row.id, keptVersion: row.version, superseded: [] })\n          keptFileName = row.target_file_name ?? ''\n          continue\n        }\n        supersede.run(row.id)\n        current.superseded.push({\n          draftId: row.id,\n          version: row.version,\n          knowledgeDocumentId: row.knowledge_document_id ?? '',\n          targetFileName: row.publication_status === 'published' && row.target_file_name !== keptFileName\n            ? row.target_file_name ?? '' : '',\n        })\n      }\n      if (chapters.length > 0) invalidateContinuityProjectionFrom(db, chapters[0]!.chapterNumber)\n      return { chapters }\n    }).immediate()\n  }\n\n  static isAuthoritative(draftId: number): boolean {\n    return requireDatabase().prepare(`\n      SELECT drafts.id FROM drafts\n      WHERE drafts.status = 'finalized'\n        AND drafts.chapter_number = (SELECT chapter_number FROM drafts WHERE id = ?)\n      ORDER BY ${AUTHORITATIVE_FINALIZED_ORDER}\n      LIMIT 1\n    `).pluck().get(draftId) === draftId\n  }\n\n  static get(finalizationId: string): FinalizationRecord | null {\n    const db = requireDatabase()\n    const row = db.prepare(`\n      SELECT * FROM finalization_outbox WHERE finalization_id = ?\n    `).get(finalizationId) as FinalizationRow | undefined\n    return row ? rowToRecord(row) : null\n  }\n\n  /** 定稿收进知识库的文档身份到章号；知识库凭它区分定稿章节与作者导入的资料（两者都写项目副本）。 */\n  static knowledgeDocumentChapters(): Map<string, number> {\n    const rows = requireDatabase().prepare(`\n      SELECT knowledge_document_id, chapter_number FROM finalization_outbox WHERE knowledge_document_id != ''\n    `).all() as Array<{ knowledge_document_id: string; chapter_number: number }>\n    return new Map(rows.map(row => [row.knowledge_document_id, row.chapter_number]))\n  }\n\n  static getByDraftId(draftId: number): FinalizationRecord | null {\n    const db = requireDatabase()\n    const row = db.prepare(`\n      SELECT * FROM finalization_outbox WHERE draft_id = ?\n    `).get(draftId) as FinalizationRow | undefined\n    return row ? rowToRecord(row) : null\n  }\n\n  static linkKnowledgeDocument(draftId: number, documentId: string): FinalizationRecord {\n    const normalizedDocumentId = documentId.trim()\n    if (!normalizedDocumentId) throw new Error('FINALIZATION_COMMIT_KNOWLEDGE_DOCUMENT_REQUIRED')\n    const db = requireDatabase()\n    const existing = db.prepare(`\n      SELECT finalization_id FROM finalization_outbox WHERE draft_id = ?\n    `).get(draftId) as { finalization_id: string } | undefined\n    if (!existing) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    readPortableRuntimeFreeze(getCurrentProjectPath()).assertMutable('finalization_outbox', existing.finalization_id)\n    const result = db.prepare(`\n      UPDATE finalization_outbox\n      SET knowledge_document_id = ?, updated_at = datetime('now')\n      WHERE draft_id = ? AND finalization_id = ?\n    `).run(normalizedDocumentId, draftId, existing.finalization_id)\n    if (result.changes !== 1) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    const record = FinalizationRepository.getByDraftId(draftId)\n    if (!record) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    return record\n  }\n\n  static markPublicationPending(finalizationId: string, error: string): FinalizationRecord {\n    const db = requireDatabase()\n    const result = db.prepare(`\n      UPDATE finalization_outbox\n      SET publication_status = 'pending', last_error = ?, updated_at = datetime('now')\n      WHERE finalization_id = ?\n    `).run(error, finalizationId)\n    if (result.changes !== 1) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    const record = FinalizationRepository.get(finalizationId)\n    if (!record) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    return record\n  }\n\n  static markPublished(finalizationId: string): FinalizationRecord {\n    const db = requireDatabase()\n    const result = db.prepare(`\n      UPDATE finalization_outbox\n      SET publication_status = 'published', last_error = '',\n          published_at = datetime('now'), updated_at = datetime('now')\n      WHERE finalization_id = ?\n    `).run(finalizationId)\n    if (result.changes !== 1) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    const record = FinalizationRepository.get(finalizationId)\n    if (!record) throw new Error('FINALIZATION_COMMIT_NOT_FOUND')\n    return record\n  }\n}\n"
    },
    {
      "path": "electron/llm/gemini-provider.ts",
      "content": "import { InBandReasoningStream, ILLMProvider, LLMGenerateOptions, LLMResponse, LLMStreamOptions } from './provider.interface'\nimport type { LLMFinishReason, ModelProfile, TokenUsage } from '../../src/shared/ipc-channels'\nimport { VisibleStreamFilter } from './visible-stream'\nimport { StreamTransportDiagnostics } from './transport-diagnostics'\nimport { providerFailureCode } from './provider-context-length'\n\nfunction assertVisibleStreamPayload(value: unknown): void {\n  const record = (input: unknown): input is Record<string, unknown> =>\n    typeof input === 'object' && input !== null && !Array.isArray(input)\n  const invalid = () => { throw new Error('LLM_STREAM_INVALID') }\n  if (!record(value)) return invalid()\n  if ('error' in value) throw new Error('LLM_STREAM_PROVIDER_ERROR')\n  if (value.candidates === undefined) return\n  if (!Array.isArray(value.candidates)) return invalid()\n  for (const candidate of value.candidates) {\n    if (!record(candidate)) return invalid()\n    if (candidate.finishReason !== undefined && candidate.finishReason !== null\n      && typeof candidate.finishReason !== 'string') return invalid()\n    if (candidate.content === undefined) continue\n    if (!record(candidate.content)) return invalid()\n    if (candidate.content.parts === undefined) continue\n    if (!Array.isArray(candidate.content.parts)) return invalid()\n    for (const part of candidate.content.parts) {\n      if (!record(part)) return invalid()\n      if (part.text !== undefined && typeof part.text !== 'string') return invalid()\n      if (part.thought !== undefined && typeof part.thought !== 'boolean') return invalid()\n    }\n  }\n}\n\ninterface GeminiUsageMetadata {\n  promptTokenCount?: number\n  candidatesTokenCount?: number\n  thoughtsTokenCount?: number\n  totalTokenCount?: number\n}\n\n/**\n * 交给调用记录的用量与 OpenAI 一致：输出含思考消耗（OpenAI 的 completion_tokens 本就含 reasoning_tokens）。\n * Gemini 的 candidatesTokenCount 只算正文，思考在 thoughtsTokenCount 里另报。\n */\nfunction geminiTokenUsage(metadata: GeminiUsageMetadata): TokenUsage {\n  // usageMetadata 是未校验的 JSON，只认非负整数；没报的分项按 0 计，报了却不是数字就整项不记。\n  const count = (value: unknown) => typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 ? value : null\n  const part = (value: unknown) => value === undefined ? 0 : count(value)\n  const candidates = part(metadata.candidatesTokenCount), thoughts = part(metadata.thoughtsTokenCount)\n  const reported = metadata.candidatesTokenCount !== undefined || metadata.thoughtsTokenCount !== undefined\n  return {\n    promptTokens: count(metadata.promptTokenCount),\n    completionTokens: reported && candidates !== null && thoughts !== null ? candidates + thoughts : null,\n    totalTokens: count(metadata.totalTokenCount),\n  }\n}\n\nexport class GeminiProvider implements ILLMProvider {\n  private applyReasoning(\n    generationConfig: Record<string, unknown>,\n    opts: LLMGenerateOptions,\n  ): void {\n    if (opts.reasoning?.adapter === 'gemini-thinking-budget') {\n      generationConfig.thinkingConfig = { thinkingBudget: opts.reasoning.thinkingBudget }\n    } else if (opts.reasoning?.adapter === 'gemini-thinking-level') {\n      generationConfig.thinkingConfig = { thinkingLevel: opts.reasoning.thinkingLevel }\n    }\n  }\n\n  private normalizeFinishReason(reason: string | null | undefined): LLMFinishReason {\n    if (reason === 'STOP') return 'stop'\n    if (reason === 'MAX_TOKENS') return 'length'\n    if (reason && ['SAFETY', 'RECITATION', 'BLOCKLIST', 'PROHIBITED_CONTENT'].includes(reason)) {\n      return 'content_filter'\n    }\n    return 'unknown'\n  }\n\n  private toGeminiContents(messages: Array<{ role: string; content: string }>) {\n    let systemInstruction: string | undefined\n    const contents: Array<{ role: string; parts: Array<{ text: string }> }> = []\n\n    for (const msg of messages) {\n      if (msg.role === 'system') {\n        systemInstruction = msg.content\n        continue\n      }\n      contents.push({\n        role: msg.role === 'assistant' ? 'model' : 'user',\n        parts: [{ text: msg.content }],\n      })\n    }\n    return { contents, systemInstruction }\n  }\n  async generate(model: ModelProfile, messages: Array<{ role: string; content: string }>, opts: LLMGenerateOptions): Promise<LLMResponse> {\n    try {\n      const baseUrl = model.baseUrl.replace(/\\/$/, '')\n      const url = `${baseUrl}/v1beta/models/${model.modelName}:generateContent`\n\n      const { contents, systemInstruction } = this.toGeminiContents(messages)\n\n      const generationConfig: Record<string, unknown> = {\n        maxOutputTokens: opts.maxTokens ?? model.maxTokens,\n      }\n      if (opts.temperature !== undefined) {\n        generationConfig.temperature = opts.temperature\n      }\n      if (opts.responseFormat?.type === 'json_object') {\n        generationConfig.responseMimeType = 'application/json'\n      }\n      this.applyReasoning(generationConfig, opts)\n\n      const body: Record<string, unknown> = {\n        contents,\n        generationConfig,\n      }\n      if (systemInstruction) {\n        body.systemInstruction = { parts: [{ text: systemInstruction }] }\n      }\n\n      const res = await fetch(url, {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json',\n          'x-goog-api-key': model.apiKey,\n        },\n        body: JSON.stringify(body),\n        signal: opts.signal,\n      })\n\n      if (!res.ok) {\n        const text = await res.text()\n        return { success: false, content: '', finishReason: 'error', error: 'LLM_REQUEST_FAILED', httpFailure: { status: res.status, body: text } }\n      }\n\n      const data = await res.json() as {\n        candidates?: Array<{\n          content?: { parts?: Array<{ text?: string }> }\n          finishReason?: string | null\n        }>\n        usageMetadata?: GeminiUsageMetadata\n      }\n\n      const text = data.candidates?.[0]?.content?.parts?.[0]?.text ?? ''\n      const finishReason = this.normalizeFinishReason(data.candidates?.[0]?.finishReason)\n      const usage = data.usageMetadata ? geminiTokenUsage(data.usageMetadata) : undefined\n\n      if (finishReason === 'stop') {\n        return {\n          success: true,\n          content: text,\n          usage,\n          finishReason,\n        }\n      }\n\n      return {\n        success: false,\n        content: text,\n        usage,\n        finishReason,\n        error: 'LLM_RESPONSE_INCOMPLETE',\n      }\n    } catch (error) {\n      return { success: false, content: '', finishReason: 'error', error: String(error) }\n    }\n  }\n\n  async generateStream(model: ModelProfile, messages: Array<{ role: string; content: string }>, opts: LLMStreamOptions): Promise<void> {\n    const transport = new StreamTransportDiagnostics(opts.onDiagnostics)\n    const visible = new VisibleStreamFilter()\n    const reasoning = (chunk: string) => { transport.output('reasoningEvents'); opts.onReasoning?.(chunk) }\n    const inBandReasoning = new InBandReasoningStream(reasoning)\n    let visibleUsage: TokenUsage | undefined\n    try {\n      const baseUrl = model.baseUrl.replace(/\\/$/, '')\n      const url = `${baseUrl}/v1beta/models/${model.modelName}:streamGenerateContent?alt=sse`\n\n      const { contents, systemInstruction } = this.toGeminiContents(messages)\n\n      const generationConfig: Record<string, unknown> = {\n        maxOutputTokens: opts.maxTokens ?? model.maxTokens,\n      }\n      if (opts.temperature !== undefined) {\n        generationConfig.temperature = opts.temperature\n      }\n      if (opts.responseFormat?.type === 'json_object') {\n        generationConfig.responseMimeType = 'application/json'\n      }\n      this.applyReasoning(generationConfig, opts)\n\n      const body: Record<string, unknown> = {\n        contents,\n        generationConfig,\n      }\n      if (systemInstruction) {\n        body.systemInstruction = { parts: [{ text: systemInstruction }] }\n      }\n\n      const res = await transport.response(fetch(url, {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json',\n          'x-goog-api-key': model.apiKey,\n        },\n        body: JSON.stringify(body),\n        signal: opts.signal,\n      }))\n\n      if (!res.ok) {\n        transport.fail('HTTP_ERROR')\n        opts.onError(await providerFailureCode(res, opts.signal))\n        return\n      }\n\n      const reader = res.body?.getReader()\n      if (!reader) {\n        transport.fail('RESPONSE_BODY_MISSING')\n        opts.onError('LLM_STREAM_UNREADABLE')\n        return\n      }\n      transport.streaming()\n\n      const decoder = new TextDecoder()\n      let fullText = ''\n      let usage: TokenUsage | undefined\n      let buffer = ''\n      let finishReason: LLMFinishReason = 'unknown'\n\n      const processLine = (line: string) => {\n        if (!line.startsWith('data: ')) return\n        const json = line.slice(6).trim()\n        if (!json) return\n        let parsed: {\n          candidates?: Array<{\n            content?: { parts?: Array<{ text?: string; thought?: boolean }> }\n            finishReason?: string | null\n          }>\n          usageMetadata?: GeminiUsageMetadata\n        }\n        try {\n          parsed = JSON.parse(json)\n          if (opts.visibleOnly) assertVisibleStreamPayload(parsed)\n        } catch (error) {\n          // Ignore non-data SSE lines and malformed keepalives unless the owner needs a valid stream.\n          if (!opts.visibleOnly) return\n          transport.errorCode(error instanceof Error && error.message === 'LLM_STREAM_PROVIDER_ERROR' ? 'PROVIDER_STREAM_ERROR' : 'STREAM_INVALID')\n          throw error\n        }\n        try {\n          const candidate = parsed.candidates?.[0]\n          if (candidate?.finishReason !== undefined) {\n            finishReason = this.normalizeFinishReason(candidate.finishReason)\n          }\n          for (const part of candidate?.content?.parts ?? []) {\n            if (part.thought === true) {\n              if (part.text) reasoning(part.text)\n            } else if (typeof part.text === 'string') {\n              inBandReasoning.push(part.text)\n            }\n          }\n          const content = (candidate?.content?.parts ?? []).filter(part => part.thought !== true)\n            .map(part => typeof part.text === 'string' ? part.text : '').join('')\n          const chunk = opts.visibleOnly ? visible.push(content ?? '') : content\n          if (chunk) {\n            transport.output('visibleEvents')\n            fullText += chunk\n            opts.onChunk(chunk)\n          }\n          if (parsed.usageMetadata) {\n            const metadata = parsed.usageMetadata\n            usage = geminiTokenUsage(metadata)\n            visibleUsage = usage\n            // 预算结算按 Gemini 的计费方式：正文与思考分开报，总量含思考。\n            opts.onUsageEvidence?.({ usage: { promptTokens: metadata.promptTokenCount ?? null,\n              completionTokens: metadata.candidatesTokenCount ?? null, totalTokens: metadata.totalTokenCount ?? null },\n            reasoningTokens: metadata.thoughtsTokenCount ?? null,\n            accounting: 'separately-billed', totalIncludesReasoning: true, protocol: 'gemini' })\n          }\n        } catch (error) {\n          if (opts.visibleOnly) throw error\n        }\n      }\n\n      let streamEnded = false\n      while (!streamEnded) {\n        const { done, value } = await transport.read(reader)\n        streamEnded = done\n        if (done) continue\n\n        buffer += decoder.decode(value, { stream: true })\n        const segments = buffer.split('\\n')\n        buffer = segments.pop() ?? ''\n        for (const line of segments) processLine(line)\n      }\n\n      buffer += decoder.decode()\n      if (buffer.trim()) processLine(buffer)\n\n      transport.completed()\n      opts.onDone(opts.visibleOnly ? visible.text : fullText, usage, finishReason)\n    } catch (error) {\n      transport.interrupted(error, opts.signal.aborted)\n      if (opts.signal.aborted) {\n        opts.onError('LLM_CANCELLED', opts.visibleOnly ? visible.text : undefined, visibleUsage)\n      } else {\n        opts.onError(transport.networkFailure ? 'LLM_STREAM_NETWORK_FAILED' : String(error), opts.visibleOnly ? visible.text : undefined, visibleUsage)\n      }\n    }\n  }\n}\n"
    }
  ],
